-- ============================================================================
-- >>> schema.sql
-- ============================================================================
-- =====================================================================
-- ZoFHub · Supabase schema  (v4 — SAFE / idempotent / advisor-clean)
-- =====================================================================
-- HOW TO RUN
--   1. Supabase Dashboard → SQL Editor → New query
--   2. Paste the whole file
--   3. Click "Run"  (expect "Success." — re-running is safe)
--
-- ✅ NON-DESTRUCTIVE: this version NEVER drops your games table, so you can
--    run it as many times as you like without losing data. (The old v3 began
--    with `drop table games` — re-running it wiped the whole catalog. Fixed.)
--    It only CREATES things that are missing and REPLACES the helper objects
--    (function / view / policy) in place.
--
-- This schema passes the Supabase Advisor Center cleanly:
--   * RLS enabled with an explicit policy            (no "RLS disabled")
--   * the trigger function pins search_path = ''      (no "mutable search_path")
--   * the view is SECURITY INVOKER                    (no "security definer view")
--   * no extensions are created in the public schema  (no "extension in public")
-- =====================================================================


-- ---------------------------------------------------------------------
-- Legacy cleanup (safe no-ops if they were never created)
-- ---------------------------------------------------------------------
-- An earlier build installed pg_trgm + GIN indexes in the public schema for
-- title search. Runtime search now runs in-memory in the Node server, so the
-- extension is unnecessary and trips the "Extension in Public" advisor. Drop
-- the dependent indexes first, then the extension. `if exists` = harmless when
-- they aren't present.
drop index if exists public.games_title_trgm_idx;
drop index if exists public.games_title_fts_idx;

-- SCOPED TO public ON PURPOSE — do not simplify this back to
-- `drop extension if exists pg_trgm cascade;`
--
-- This project has NO migration ledger, so every file here re-runs on EVERY
-- merge to main, forever. An unscoped drop is therefore not a one-time cleanup:
-- it is a statement that deletes pg_trgm on every deploy for the rest of the
-- project's life. The moment anyone enables pg_trgm for a legitimate reason —
-- Supabase installs it into the `extensions` schema, not public — the next
-- deploy silently removes it, and CASCADE takes every dependent index with it.
-- No error, no log line: the feature that depended on it just stops working.
--
-- The problem this cleanup actually solves is the extension being in PUBLIC,
-- which is the only thing the advisor flags. So check for exactly that. An
-- extension deliberately installed in `extensions` is left alone.
do $$
begin
  if exists (
    select 1
      from pg_extension e
      join pg_namespace n on n.oid = e.extnamespace
     where e.extname = 'pg_trgm'
       and n.nspname = 'public'
  ) then
    execute 'drop extension pg_trgm cascade';
    raise notice 'dropped pg_trgm from the public schema (legacy cleanup)';
  end if;
end $$;


-- ---------------------------------------------------------------------
-- Table (created only if it doesn't already exist — your data is kept)
-- ---------------------------------------------------------------------
create table if not exists public.games (
  id            bigint generated by default as identity primary key,
  slug          text         not null unique,
  title         varchar(255) not null,
  game_url      text         not null,
  thumbnail_url text,
  category      text         not null default 'arcade',
  is_working    boolean      not null default true,
  last_checked  timestamptz  not null default now(),
  created_at    timestamptz  not null default now(),
  updated_at    timestamptz  not null default now()
);

-- Backfill any columns that an older version of the table might be missing,
-- without touching existing rows. (No-ops once the column is present.)
alter table public.games add column if not exists thumbnail_url text;
alter table public.games add column if not exists category     text        not null default 'arcade';
alter table public.games add column if not exists is_working   boolean     not null default true;
alter table public.games add column if not exists last_checked timestamptz not null default now();
alter table public.games add column if not exists created_at   timestamptz not null default now();
alter table public.games add column if not exists updated_at   timestamptz not null default now();

comment on table  public.games               is 'ZoFHub game catalog — source of truth for /api/games. Updated by hourly cron.';
comment on column public.games.slug          is 'URL-safe stable identifier. UNIQUE — primary dedupe key across sources.';
comment on column public.games.title         is 'Display name. Max 255 chars.';
comment on column public.games.game_url      is 'Publisher iframe src — used by /play/:slug as the iframe target.';
comment on column public.games.thumbnail_url is 'Image URL. NULL → frontend swaps to /default-placeholder.svg.';
comment on column public.games.category      is 'Free-form category slug (puzzle / racing / arcade / etc). Default = arcade.';
comment on column public.games.is_working    is 'Set false by hourly link-check when HEAD returns 4xx/5xx/timeout.';
comment on column public.games.last_checked  is 'Last time link-check probed game_url. Cron uses this for ASC ordering.';
comment on column public.games.created_at    is 'First seen by migration.';
comment on column public.games.updated_at    is 'Auto-bumped on every UPDATE by trg_games_updated_at trigger.';


-- ---------------------------------------------------------------------
-- Indexes — cover the queries the server + cron actually run.
-- (Runtime title search is in-memory in Node, so no GIN/trigram index here.)
-- ---------------------------------------------------------------------

-- Hot read: WHERE is_working = true ORDER BY id DESC LIMIT N OFFSET X
create index if not exists games_working_id_desc_idx
  on public.games (is_working, id desc);

-- Cron: WHERE is_working = true ORDER BY last_checked ASC LIMIT N
create index if not exists games_working_lastchecked_idx
  on public.games (is_working, last_checked asc);

-- Category pages: WHERE category = $1 (only working rows).
create index if not exists games_category_idx
  on public.games (category) where is_working = true;

-- NOTE: the UNIQUE constraint on `slug` already creates a btree index.


-- ---------------------------------------------------------------------
-- updated_at auto-bump trigger
-- ---------------------------------------------------------------------
-- SECURITY INVOKER + empty search_path is the Supabase-recommended hardening
-- (clears the "Function Search Path Mutable" advisor). now() resolves from
-- pg_catalog, which is always implicitly available even with search_path = ''.
create or replace function public.games_set_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists trg_games_updated_at on public.games;
create trigger trg_games_updated_at
  before update on public.games
  for each row execute function public.games_set_updated_at();


-- ---------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------
-- Anon / publishable key may only READ working games. The service-role key
-- (used by the Node server for cron link-check + migration) bypasses RLS.
alter table public.games enable row level security;

drop policy if exists "Public can read working games" on public.games;
create policy "Public can read working games"
  on public.games for select
  using (is_working = true);


-- ---------------------------------------------------------------------
-- Frontend-shaped view (SECURITY INVOKER so it respects the caller's RLS)
-- ---------------------------------------------------------------------
-- `games_public` is what /api/games queries. It pre-applies the is_working
-- filter and substitutes a placeholder when thumbnail is NULL/empty.
create or replace view public.games_public
with (security_invoker = true) as
  select
    id,
    slug,
    title,
    game_url,
    coalesce(nullif(thumbnail_url, ''), '/default-placeholder.svg') as thumbnail_url,
    category,
    last_checked
  from public.games
  where is_working = true;

comment on view public.games_public is 'Frontend projection of public.games — pre-filtered to is_working=true with thumbnail fallback. SECURITY INVOKER.';


-- ---------------------------------------------------------------------
-- Sanity check (how many games are live right now)
-- ---------------------------------------------------------------------
select count(*) as games_count from public.games;


-- ============================================================================
-- >>> community.sql
-- ============================================================================
-- =====================================================================
-- ZoFHub · community schema  (recommendations + leaderboard)
-- =====================================================================
-- ADDITIVE & SAFE: uses CREATE TABLE IF NOT EXISTS and touches NOTHING in
-- the existing `games` table. Run it once in the Supabase SQL Editor:
--   Dashboard → SQL Editor → New query → paste → Run.
--
-- Two tables:
--   recommendations — user-submitted "you should add/play this" entries,
--                     each with an embeddable game URL + a short note.
--   scores          — player-reported leaderboard entries per game.
--
-- Security model (matches the rest of ZoFHub):
--   * RLS ON. Public (anon key) may only SELECT.
--   * All writes go through the Node server using the SERVICE-ROLE key,
--     which bypasses RLS — so the server can validate/sanitize every insert
--     (trusted-host check on embed_url, length limits, rate basics) before
--     it ever reaches the DB. The browser can never write directly.
-- =====================================================================

-- ---------------------------------------------------------------------
-- recommendations
-- ---------------------------------------------------------------------
create table if not exists public.recommendations (
  id          bigint generated by default as identity primary key,
  title       varchar(120) not null,
  embed_url   text         not null,
  note        varchar(280),
  author      varchar(40)  not null default 'Anonymous',
  category    text         not null default 'arcade',
  views       integer      not null default 0,
  is_visible  boolean      not null default true,
  created_at  timestamptz  not null default now(),
  last_seen_at timestamptz not null default now()
);

comment on table public.recommendations is 'Community-submitted game recommendations. Embed URLs are validated against the trusted-host allowlist server-side before insert.';

-- Feed ordering: newest visible first.
create index if not exists recommendations_visible_created_idx
  on public.recommendations (is_visible, created_at desc);
-- Cleanup ordering: find least-viewed / oldest cheaply.
create index if not exists recommendations_views_created_idx
  on public.recommendations (views asc, created_at asc);

alter table public.recommendations enable row level security;
drop policy if exists "Public can read visible recommendations" on public.recommendations;
create policy "Public can read visible recommendations"
  on public.recommendations for select using (is_visible = true);

-- ---------------------------------------------------------------------
-- scores (leaderboard)
-- ---------------------------------------------------------------------
create table if not exists public.scores (
  id          bigint generated by default as identity primary key,
  slug        text         not null,
  player_name varchar(40)  not null default 'Player',
  score       bigint       not null default 0,
  status      text         not null default 'ok',   -- 'ok' = visible, 'flagged' = quarantined outlier
  flag_reason text,
  created_at  timestamptz  not null default now()
);

comment on table public.scores is 'Player-reported leaderboard scores per game slug. status=ok is public; flagged rows are held for review (see db/community-scores-integrity.sql).';

-- Per-game leaderboard: WHERE slug = $1 ORDER BY score DESC.
create index if not exists scores_slug_score_idx on public.scores (slug, score desc);
-- Global leaderboard: ORDER BY score DESC.
create index if not exists scores_score_idx on public.scores (score desc);
-- Best-per-player lookup: the score POST does WHERE slug = $1 AND player_name = $2
-- (keep-best dedupe). This index makes that exact lookup an index seek.
create index if not exists scores_slug_player_idx on public.scores (slug, player_name);
-- Visible-scores read path (public board only ever shows status='ok').
create index if not exists scores_status_score_idx on public.scores (status, score desc);

alter table public.scores enable row level security;
drop policy if exists "Public can read scores" on public.scores;
drop policy if exists "Public can read visible scores" on public.scores;
create policy "Public can read visible scores"
  on public.scores for select using (status = 'ok');

-- ---------------------------------------------------------------------
-- prune_scores() — keep the leaderboard BOUNDED so storage can't run away.
-- Two set-based deletes:
--   1. Purge quarantined ('flagged') rows older than 7 days — they're never
--      shown, so holding them only lets a cheater bloat the table.
--   2. Keep only the top `keep_per_game` VISIBLE ('ok') scores per game and
--      delete the long tail. Flagged rows are EXCLUDED from this ranking, so a
--      fake outlier can never survive in place of (or crowd out) a real score.
-- Together with the one-row-per-(game,player) keep-best dedupe the score API
-- enforces, this hard-caps the table at ~keep_per_game × (games with scores).
-- Called daily by the Node cron via RPC: supa.rpc('prune_scores', {...}).
-- SECURITY DEFINER so the service role can run it; not exposed to anon.
-- ---------------------------------------------------------------------
create or replace function public.prune_scores(keep_per_game integer default 200)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  removed integer := 0;
  n integer;
begin
  -- 1) Old quarantined rows.
  delete from public.scores
  where status is distinct from 'ok'
    and created_at < now() - interval '7 days';
  get diagnostics n = row_count;  removed := removed + n;

  -- 2) Long tail of visible scores, per game.
  with ranked as (
    select id,
           row_number() over (partition by slug order by score desc, created_at asc) as rn
    from public.scores
    where status is not distinct from 'ok'
  )
  delete from public.scores s
  using ranked r
  where s.id = r.id and r.rn > keep_per_game;
  get diagnostics n = row_count;  removed := removed + n;

  return removed;
end;
$$;

-- ---------------------------------------------------------------------
-- prune_recommendations() — hard-cap the community feed so it can't grow
-- forever. Keeps the newest `keep` rows and deletes the rest. Complements the
-- server's daily "delete >30d old AND <3 views" pass (which leaves popular old
-- posts in place); this guarantees an absolute ceiling regardless of views.
-- ---------------------------------------------------------------------
create or replace function public.prune_recommendations(keep integer default 1000)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare removed integer;
begin
  with ranked as (
    select id, row_number() over (order by created_at desc) as rn
    from public.recommendations
  )
  delete from public.recommendations r
  using ranked k
  where r.id = k.id and k.rn > keep;
  get diagnostics removed = row_count;
  return removed;
end;
$$;

-- Only the server (service role / postgres) may prune; never the public anon key.
revoke all on function public.prune_scores(integer)          from public, anon, authenticated;
revoke all on function public.prune_recommendations(integer) from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- Sanity check
-- ---------------------------------------------------------------------
select
  (select count(*) from public.recommendations) as recommendations,
  (select count(*) from public.scores)          as scores;


-- ============================================================================
-- >>> community-scores-integrity.sql
-- ============================================================================
-- =====================================================================
-- ZoFHub · scores integrity add-on   (run ONCE in the Supabase SQL editor)
-- =====================================================================
-- ADDITIVE & SAFE. Adds a moderation status to the existing `scores` table so
-- the Node server can QUARANTINE suspicious high scores (outliers) instead of
-- showing them on the public leaderboard, and upgrades the cleanup functions so
-- the tables stay BOUNDED (flagged rows are purged/excluded; the community feed
-- gets a hard ceiling). Existing rows default to 'ok' and stay visible.
-- Re-runnable (IF NOT EXISTS / OR REPLACE everywhere).
--
-- Until you run this, the server still enforces the two strongest defenses
-- (single-use proof-of-play sessions + per-game score ceilings); it just can't
-- hold outliers for review. After you run it, quarantine turns on automatically
-- the next time the server probes the table.
--
--   Dashboard → SQL Editor → New query → paste → Run.
-- =====================================================================

-- 1) Moderation columns.
alter table public.scores add column if not exists status      text not null default 'ok';
alter table public.scores add column if not exists flag_reason text;

-- 2) Index the common read path: visible ('ok') rows ordered by score.
create index if not exists scores_status_score_idx on public.scores (status, score desc);

-- 3) Tighten RLS so the public anon key can only ever read VISIBLE scores.
--    The Node server reads with the service-role key (bypasses RLS) and still
--    sees flagged rows for moderation.
drop policy if exists "Public can read scores" on public.scores;
drop policy if exists "Public can read visible scores" on public.scores;
create policy "Public can read visible scores"
  on public.scores for select using (status = 'ok');

-- 4) Status-aware cleanup: purge old flagged rows + keep only the top VISIBLE
--    scores per game (flagged rows excluded from the ranking so a fake outlier
--    can't survive in place of a real score). Replaces the old prune_scores.
create or replace function public.prune_scores(keep_per_game integer default 200)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  removed integer := 0;
  n integer;
begin
  delete from public.scores
  where status is distinct from 'ok'
    and created_at < now() - interval '7 days';
  get diagnostics n = row_count;  removed := removed + n;

  with ranked as (
    select id,
           row_number() over (partition by slug order by score desc, created_at asc) as rn
    from public.scores
    where status is not distinct from 'ok'
  )
  delete from public.scores s
  using ranked r
  where s.id = r.id and r.rn > keep_per_game;
  get diagnostics n = row_count;  removed := removed + n;

  return removed;
end;
$$;

-- 5) Hard-cap the community feed (keep newest `keep`, delete the rest).
create or replace function public.prune_recommendations(keep integer default 1000)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare removed integer;
begin
  with ranked as (
    select id, row_number() over (order by created_at desc) as rn
    from public.recommendations
  )
  delete from public.recommendations r
  using ranked k
  where r.id = k.id and k.rn > keep;
  get diagnostics removed = row_count;
  return removed;
end;
$$;

revoke all on function public.prune_scores(integer)          from public, anon, authenticated;
revoke all on function public.prune_recommendations(integer) from public, anon, authenticated;

-- 6) Sanity check.
select
  count(*) filter (where status = 'ok')      as visible,
  count(*) filter (where status = 'flagged') as flagged
from public.scores;


-- ============================================================================
-- >>> community-scores-review.sql
-- ============================================================================
-- =====================================================================
-- ZoFHub · flagged-score REVIEW add-on   (run ONCE in the Supabase SQL editor)
-- =====================================================================
-- ADDITIVE & SAFE. Re-runnable (OR REPLACE everywhere). Run this AFTER
-- db/community-scores-integrity.sql.
--
-- WHY THIS EXISTS
-- Before this, a quarantined score's real lifecycle was:
--     flagged -> invisible to everyone -> DELETED by prune_scores after 7 days
-- with no code path anywhere that could ever un-flag it. The player was still
-- told "pending review", so a genuinely great score could trip the outlier
-- heuristic, be hidden, and then vanish a week later — a promise the app could
-- not keep.
--
-- There is now a real review path (the private /admin console + the
-- /api/admin/scores/:id/approve|reject endpoints). This migration makes the
-- database agree with it:
--   * UNREVIEWED ('flagged') rows are NEVER auto-deleted — they wait for you.
--   * Only rows you actively REJECTED are purged, 7 days after rejection.
--   * The per-game "keep top N visible" cap is unchanged.
--
--   Dashboard -> SQL Editor -> New query -> paste -> Run.
-- =====================================================================

-- Status-aware cleanup, review-safe.
--   status 'ok'       -> public, capped at keep_per_game per slug
--   status 'flagged'  -> awaiting YOUR review; kept indefinitely
--   status 'rejected' -> you said no; purged after 7 days
create or replace function public.prune_scores(keep_per_game integer default 200)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  removed integer := 0;
  n integer;
begin
  -- 1) Purge only REJECTED rows. 'flagged' (unreviewed) rows are deliberately
  --    NOT touched — deleting them is what made "pending review" a false promise.
  delete from public.scores
  where status = 'rejected'
    and created_at < now() - interval '7 days';
  get diagnostics n = row_count;  removed := removed + n;

  -- 2) Long tail of VISIBLE scores, per game (unchanged).
  with ranked as (
    select id,
           row_number() over (partition by slug order by score desc, created_at asc) as rn
    from public.scores
    where status is not distinct from 'ok'
  )
  delete from public.scores s
  using ranked r
  where s.id = r.id and r.rn > keep_per_game;
  get diagnostics n = row_count;  removed := removed + n;

  return removed;
end;
$$;

revoke all on function public.prune_scores(integer) from public, anon, authenticated;

-- Sanity check: what is waiting for review right now?
select
  count(*) filter (where status = 'ok')       as visible,
  count(*) filter (where status = 'flagged')  as awaiting_review,
  count(*) filter (where status = 'rejected') as rejected
from public.scores;


-- ============================================================================
-- >>> community-scores-unique.sql
-- ============================================================================
-- =====================================================================
-- ZoFHub · one-row-per-player-per-game UNIQUENESS  (run ONCE in Supabase)
-- =====================================================================
-- ADDITIVE & SAFE. Re-runnable (IF NOT EXISTS / OR REPLACE everywhere).
-- Run AFTER db/community.sql and db/community-scores-integrity.sql.
--
-- WHY THIS EXISTS
-- "One row per player per game (their best score)" was enforced ONLY in
-- application code: SELECT existing -> if higher UPDATE else INSERT. Between the
-- SELECT and the INSERT nothing stopped two concurrent submissions (the same
-- player in two tabs, a double-tap, a retry) from both seeing "no existing row"
-- and both inserting — producing duplicate rows for the same (slug, player_name).
-- scores_slug_player_idx was a PLAIN index, not UNIQUE, so the database happily
-- allowed it. /leaderboard hid the damage with a client-side dedupe; /community
-- did not, so the same data could render differently on the two pages.
--
-- WHAT THIS DOES
--   1. De-duplicates existing VISIBLE rows, keeping each player's highest score
--      per game (ties -> the earliest, matching prune_scores' ordering).
--      'flagged' / 'rejected' rows are NOT touched (see community-scores-review.sql).
--   2. Adds a PARTIAL UNIQUE index on (slug, player_name) WHERE status = 'ok'.
--      Partial on purpose: a player may legitimately have one visible row AND a
--      later attempt sitting in the flagged queue — a full unique index would
--      make that collide and reject the quarantine insert.
--   3. Installs submit_score(), an ATOMIC keep-the-best upsert the server calls
--      instead of select-then-branch. INSERT ... ON CONFLICT is what actually
--      makes the rule race-proof. (A partial unique index needs the matching
--      WHERE predicate in ON CONFLICT, which PostgREST's upsert cannot express —
--      that is why this is a function rather than a plain .upsert() call.)
--
--   Dashboard -> SQL Editor -> New query -> paste -> Run.
-- =====================================================================

-- 1) Report + remove duplicate VISIBLE rows, keeping each player's best.
do $$
declare dupes integer;
begin
  select count(*) into dupes
  from (
    select id, row_number() over (
             partition by slug, player_name
             order by score desc, created_at asc
           ) as rn
    from public.scores
    where status is not distinct from 'ok'
  ) t
  where t.rn > 1;
  raise notice 'Duplicate visible rows to remove: %', dupes;
end $$;

with ranked as (
  select id, row_number() over (
           partition by slug, player_name
           order by score desc, created_at asc
         ) as rn
  from public.scores
  where status is not distinct from 'ok'
)
delete from public.scores s
using ranked r
where s.id = r.id and r.rn > 1;

-- 2) The real constraint. Partial: only VISIBLE rows must be unique.
create unique index if not exists scores_slug_player_ok_uidx
  on public.scores (slug, player_name)
  where status = 'ok';

-- 3) Atomic "keep the best score" upsert.
--    Returns the resulting best plus whether this call created / raised it, so
--    the API can keep its existing { created, updated, best } response shape.
create or replace function public.submit_score(
  p_slug   text,
  p_player text,
  p_score  bigint
)
returns table (best bigint, updated boolean, created boolean)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_prev bigint;
begin
  select s.score into v_prev
    from public.scores s
   where s.slug = p_slug and s.player_name = p_player and s.status = 'ok'
   limit 1;

  -- The atomic part: concurrent callers serialize here, so a duplicate row can
  -- never be created no matter how the requests interleave.
  insert into public.scores (slug, player_name, score, status, flag_reason)
  values (p_slug, p_player, p_score, 'ok', null)
  on conflict (slug, player_name) where status = 'ok'
  do update
     set score      = greatest(public.scores.score, excluded.score),
         created_at = case when excluded.score > public.scores.score
                           then now() else public.scores.created_at end,
         flag_reason = null;

  if v_prev is null then
    return query select p_score, false, true;
  elsif p_score > v_prev then
    return query select p_score, true, false;
  else
    return query select v_prev, false, false;
  end if;
end;
$$;

revoke all on function public.submit_score(text, text, bigint) from public, anon, authenticated;

-- 4) Sanity check: this must return 0 rows once the constraint is in place.
select slug, player_name, count(*) as copies
from public.scores
where status is not distinct from 'ok'
group by slug, player_name
having count(*) > 1;


-- ============================================================================
-- >>> keepalive.sql
-- ============================================================================
-- ZoFHub · keep-alive status table  (OPTIONAL but recommended)
-- ============================================================================
-- One row. The daily cron job and the /healthz endpoint upsert `last_pinged`
-- here so (a) your free-tier Supabase project sees a write and never hits its
-- 7-day inactivity pause, and (b) you can SEE the last heartbeat time.
--
-- The app also works WITHOUT this table — supabaseKeepAlive() falls back to a
-- tiny read — so running this is optional. With it, you get a visible marker.
--
-- HOW TO RUN: Supabase -> SQL Editor -> New query -> paste -> Run. Safe to re-run.
-- Security: RLS on. Public may read the status; only the server (service-role
-- key, which bypasses RLS) writes it.
-- ============================================================================
create table if not exists public.keepalive (
  id          smallint    primary key default 1,
  last_pinged timestamptz not null default now(),
  constraint keepalive_single_row check (id = 1)
);

-- Seed the single row so the first upsert has a row to update.
insert into public.keepalive (id) values (1) on conflict (id) do nothing;

alter table public.keepalive enable row level security;
drop policy if exists "Public can read keepalive" on public.keepalive;
create policy "Public can read keepalive"
  on public.keepalive for select using (true);

-- Sanity check
select id, last_pinged from public.keepalive;


-- ============================================================================
-- >>> stats.sql
-- ============================================================================
-- db/stats.sql — OPTIONAL. Makes "how much each game is played" survive restarts.
-- ============================================================================
-- The site ranks games by popularity (play counts) and shuffles the order per
-- visitor. It works WITHOUT this table — play counts just live in memory and
-- reset whenever the server restarts/redeploys. Run this once and the counts
-- persist and keep accumulating, so ranking gets better over time.
--
-- HOW TO RUN:  Supabase → SQL Editor → New query → paste → Run.
--             Expect "Success. No rows returned." Safe to re-run.
--
-- Security model (matches the rest of ZoFHub):
--   * RLS ON. Public (anon key) may only SELECT.
--   * Writes happen ONLY from the Node server using the service-role key, which
--     bypasses RLS — the browser can never write play counts directly.
-- ============================================================================

create table if not exists public.game_stats (
  slug        text        primary key,
  plays       bigint      not null default 0,
  updated_at  timestamptz not null default now()
);

comment on table public.game_stats is 'Lifetime play counts per game slug. Written server-side (service role) by POST /api/play flushes; powers popularity ranking.';

-- Find the most-played games quickly (for any future "Top games" query).
create index if not exists game_stats_plays_idx on public.game_stats (plays desc);

alter table public.game_stats enable row level security;
drop policy if exists "Public can read game_stats" on public.game_stats;
create policy "Public can read game_stats"
  on public.game_stats for select using (true);


-- ============================================================================
-- >>> game-fingerprints.sql
-- ============================================================================
-- db/game-fingerprints.sql
--
-- Storage for the game discovery engine (lib/game-discovery.mjs): the provider
-- identity of every catalog entry, plus a record of duplicates it finds.
--
-- WHY A FINGERPRINT COLUMN AND NOT A UNIQUE INDEX ON game_url
-- The same game reaches us under many URLs — different portals, different
-- partner subdomains, tracking parameters, www or not. A unique index on
-- game_url would treat every one of those as a distinct game, which is exactly
-- how the catalog ended up with 4,691 rows (27.7%) sharing a title. The
-- fingerprint is `provider:id`, which is stable across all of that, so the
-- constraint can live where the real identity is.
--
-- The gamezop case is the clearest example: the partner id sits in the
-- SUBDOMAIN, so 4665.play.gamezop.com and zv1y2i8p.play.gamezop.com are
-- different hosts serving the same game. This catalog holds 129 games on one
-- and 99 on the other.
--
-- Idempotent (IF NOT EXISTS / guarded DROPs), so re-applying it to a database
-- that already has this schema is a no-op rather than an error.

create table if not exists public.game_fingerprints (
  id           bigserial primary key,
  slug         text not null,
  -- `provider:id` — e.g. gamezop:xyz789, y8:turn_and_hit
  fingerprint  text not null,
  provider     text not null,
  provider_id  text not null,
  -- Canonical URL: https, no www, no tracking params, sorted query, no hash.
  canonical_url text not null,
  -- Title reduced to a comparison key, for the weaker title-only signal.
  title_key    text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

-- One row per catalog game.
create unique index if not exists game_fingerprints_slug_uidx
  on public.game_fingerprints (slug);

-- The lookup that answers "do we already have this game?" in one indexed hit,
-- instead of scanning 16,913 rows in application code.
create index if not exists game_fingerprints_fp_idx
  on public.game_fingerprints (fingerprint);
create index if not exists game_fingerprints_canonical_idx
  on public.game_fingerprints (canonical_url);
create index if not exists game_fingerprints_title_idx
  on public.game_fingerprints (title_key);

-- Duplicate relationships found by the engine. Kept as a RELATION rather than
-- deleting the loser, because "same title" is evidence and not proof — two
-- different games really are both called "Bubble Shooter". A human resolves
-- `status`; nothing is destroyed by the detector.
create table if not exists public.game_duplicates (
  id            bigserial primary key,
  slug          text not null,          -- the newer / candidate entry
  duplicate_of  text not null,          -- the entry it appears to duplicate
  -- same_url | same_provider_id | same_title
  match_kind    text not null,
  -- exact | likely
  confidence    text not null default 'likely',
  -- pending | confirmed | rejected
  status        text not null default 'pending',
  detected_at   timestamptz not null default now(),
  resolved_at   timestamptz,
  constraint game_duplicates_not_self check (slug <> duplicate_of)
);

create unique index if not exists game_duplicates_pair_uidx
  on public.game_duplicates (slug, duplicate_of);
create index if not exists game_duplicates_status_idx
  on public.game_duplicates (status, detected_at desc);

-- Submitted URLs that failed safety validation. Worth keeping: a spike of
-- rejected submissions from one source is an abuse signal, and without a record
-- the only evidence a submission was ever made is that it silently vanished.
create table if not exists public.rejected_submissions (
  id          bigserial primary key,
  url         text not null,
  reason      text not null,            -- not_https | internal_address | ...
  submitted_at timestamptz not null default now()
);

create index if not exists rejected_submissions_at_idx
  on public.rejected_submissions (submitted_at desc);

-- ── RLS ───────────────────────────────────────────────────────────────────
-- These tables are operational metadata, not public content. The anon key gets
-- nothing; the server reaches them with the service key, which bypasses RLS.
-- Enabling RLS with no permissive policy is therefore deny-by-default, which is
-- the correct posture for a table the public has no reason to read.
alter table public.game_fingerprints   enable row level security;
alter table public.game_duplicates     enable row level security;
alter table public.rejected_submissions enable row level security;

drop policy if exists "No public access to fingerprints" on public.game_fingerprints;
drop policy if exists "No public access to duplicates"   on public.game_duplicates;
drop policy if exists "No public access to rejections"   on public.rejected_submissions;

-- updated_at maintenance, matching the pattern used by public.games.
create or replace function public.touch_game_fingerprints()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end $$;

drop trigger if exists trg_game_fingerprints_updated_at on public.game_fingerprints;
create trigger trg_game_fingerprints_updated_at
  before update on public.game_fingerprints
  for each row execute function public.touch_game_fingerprints();


-- ============================================================================
-- >>> admin.sql
-- ============================================================================
-- db/admin.sql
--
-- Storage for the administrator console: sessions, audit trail, login attempts
-- and security events.
--
-- WHY THESE LIVE IN POSTGRES AND NOT IN MEMORY
-- The app already carries four in-memory structures that make it correct only on
-- a single instance (score sessions, rate-limit buckets, presence, play counts).
-- Admin state must not join that list: an in-memory session table means every
-- deploy silently logs the operator out, and a second replica would accept a
-- session the first one never issued. It also means the audit trail — the one
-- record that has to survive an incident — would be erased by the restart that
-- often FOLLOWS an incident.
--
-- FAIL CLOSED. Every table here is reachable only with the server's secret key.
-- If the database is unavailable the admin console cannot create or validate a
-- session, so it refuses logins rather than falling back to something weaker.
--
-- Idempotent (IF NOT EXISTS / guarded DROPs), so re-applying is a no-op.

-- ── Sessions ───────────────────────────────────────────────────────────────
-- The cookie carries a random token; this table stores only its SHA-256 HASH.
-- A dump of this table therefore grants nobody a session, exactly as a password
-- table stores hashes rather than passwords.
create table if not exists public.admin_sessions (
  id             bigserial primary key,
  -- sha256(token) — never the token itself
  token_hash     text        not null,
  username       text        not null,
  -- HMAC of the client IP, not the IP. Enough to spot a session moving between
  -- networks; useless for locating anyone.
  ip_hash        text,
  user_agent     text,
  created_at     timestamptz not null default now(),
  last_seen_at   timestamptz not null default now(),
  -- Absolute cap: a session dies at this time no matter how active it is.
  expires_at     timestamptz not null,
  revoked_at     timestamptz,
  revoked_reason text
);

create unique index if not exists admin_sessions_token_uidx
  on public.admin_sessions (token_hash);
-- The sweep and the "active sessions" panel both read this.
create index if not exists admin_sessions_live_idx
  on public.admin_sessions (expires_at desc) where revoked_at is null;

-- ── Audit trail ────────────────────────────────────────────────────────────
-- APPEND ONLY. Nothing in the dashboard can edit or delete a row here: the API
-- exposes no update or delete path, and the trigger below refuses both at the
-- database level, so even a bug in application code cannot rewrite history.
create table if not exists public.admin_audit_logs (
  id           bigserial primary key,
  at           timestamptz not null default now(),
  username     text,
  action       text        not null,   -- 'score.approve', 'game.hide', …
  target       text,                   -- what it acted on
  outcome      text        not null,   -- success | failure | denied
  ip_hash      text,
  user_agent   text,
  detail       jsonb
);

create index if not exists admin_audit_at_idx     on public.admin_audit_logs (at desc);
create index if not exists admin_audit_action_idx on public.admin_audit_logs (action, at desc);

-- Immutability enforced where it cannot be argued with.
create or replace function public.admin_audit_is_append_only()
returns trigger
language plpgsql
as $$
begin
  raise exception 'admin_audit_logs is append-only (attempted %)', tg_op;
end $$;

drop trigger if exists trg_admin_audit_no_update on public.admin_audit_logs;
create trigger trg_admin_audit_no_update
  before update or delete on public.admin_audit_logs
  for each row execute function public.admin_audit_is_append_only();

-- ── Login attempts ─────────────────────────────────────────────────────────
-- Drives lockout and gives the Security Centre something factual to show. Both
-- successes and failures are recorded: a success from an unfamiliar network is
-- the more interesting event of the two.
create table if not exists public.admin_login_attempts (
  id         bigserial primary key,
  at         timestamptz not null default now(),
  username   text,                    -- as SUPPLIED; never proves the account exists
  ok         boolean     not null,
  ip_hash    text,
  user_agent text,
  reason     text                     -- bad_password | unknown_user | locked | ok
);

create index if not exists admin_login_at_idx on public.admin_login_attempts (at desc);
create index if not exists admin_login_ip_idx on public.admin_login_attempts (ip_hash, at desc);

-- ── Security events ────────────────────────────────────────────────────────
-- Anything worth an operator's attention that is not a plain login: a session
-- whose IP or user agent changed mid-life, a CSRF rejection, a lockout starting.
create table if not exists public.admin_security_events (
  id         bigserial primary key,
  at         timestamptz not null default now(),
  kind       text        not null,    -- session_ip_change | csrf_reject | lockout | …
  severity   text        not null default 'info',   -- info | warn | critical
  username   text,
  ip_hash    text,
  detail     jsonb
);

create index if not exists admin_sec_at_idx   on public.admin_security_events (at desc);
create index if not exists admin_sec_kind_idx on public.admin_security_events (kind, at desc);

-- ── RLS ────────────────────────────────────────────────────────────────────
-- Deny by default, with NO permissive policy. The publishable key that reaches
-- browsers gets nothing at all; the server reaches these with the secret key,
-- which bypasses RLS. This is operational security data — there is no version of
-- "the public may read some of it" that makes sense.
alter table public.admin_sessions        enable row level security;
alter table public.admin_audit_logs      enable row level security;
alter table public.admin_login_attempts  enable row level security;
alter table public.admin_security_events enable row level security;

drop policy if exists "No public access to admin_sessions"        on public.admin_sessions;
drop policy if exists "No public access to admin_audit_logs"      on public.admin_audit_logs;
drop policy if exists "No public access to admin_login_attempts"  on public.admin_login_attempts;
drop policy if exists "No public access to admin_security_events" on public.admin_security_events;

-- ── Retention ──────────────────────────────────────────────────────────────
-- Called by the daily cron. Expired sessions and stale attempt rows are noise;
-- the AUDIT TRAIL IS NEVER TOUCHED by this function, deliberately — it is the
-- record you need long after everything else has aged out.
create or replace function public.prune_admin_state(
  session_grace_days integer default 7,
  attempt_days       integer default 30,
  event_days         integer default 180
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  delete from public.admin_sessions
    where expires_at < now() - make_interval(days => session_grace_days);
  delete from public.admin_login_attempts
    where at < now() - make_interval(days => attempt_days);
  delete from public.admin_security_events
    where at < now() - make_interval(days => event_days);
end $$;

-- Only the service role may prune; never the publishable key.
revoke all on function public.prune_admin_state(integer, integer, integer) from public, anon, authenticated;


-- ============================================================================
-- >>> community-scores-evidence.sql
-- ============================================================================
-- ============================================================================
--  scores.flag_evidence — why a score was quarantined, in reviewable detail
--  Run AFTER db/community-scores-integrity.sql (which adds status/flag_reason).
--
--  WHY THIS EXISTS
--  Quarantine already worked, but the only thing recorded about a held score was
--  the literal string 'outlier'. An administrator reviewing the queue therefore
--  saw a score and a game and had to decide, from nothing, whether a human could
--  have produced it. The numbers that triggered the flag — the board best at the
--  time, the ratio, how long the session had actually been played, the implied
--  points per second — all existed in the request handler and were thrown away.
--
--  Keeping them turns "approve or reject, on vibes" into a decision with
--  evidence attached, and makes it possible to tune the detector afterwards:
--  you can look at what was flagged, see the distribution of ratios, and move a
--  threshold knowing what it would have caught.
--
--  jsonb, not more columns, because the detector will grow signals over time and
--  each one should not be a migration. Nothing queries inside it in the hot path;
--  it is read by the admin review screen, one row at a time.
--
--  Idempotent: safe to re-run.
-- ============================================================================

alter table public.scores add column if not exists flag_evidence jsonb;

comment on column public.scores.flag_evidence is
  'Anti-cheat detail captured when a score was flagged: the rule that fired, the '
  'board best it was compared against, the ratio, the measured play time, and the '
  'implied points-per-second. Read by the admin review screen. Null for scores '
  'that were never flagged.';

-- Reviewing the queue means "flagged rows, newest first". Without this the
-- review screen sequential-scans a table that grows forever.
create index if not exists scores_flagged_recent_idx
  on public.scores (created_at desc)
  where status = 'flagged';

-- ---------------------------------------------------------------------------
-- Duplicate / replay detection support.
--
-- The keep-best rule already collapses one player's repeated scores in a game to
-- a single row, so floods were bounded — but only per NAME. The same client
-- submitting an identical score under a series of names left no trace, because
-- nothing recorded that the submissions were related.
--
-- ip_tag is the keyed HMAC of the submitter's address (never the address
-- itself — same construction as the admin audit trail), so "these twelve rows
-- came from one place" is answerable without storing anyone's IP.
-- ---------------------------------------------------------------------------
alter table public.scores add column if not exists ip_tag text;

comment on column public.scores.ip_tag is
  'Keyed HMAC of the submitting IP, truncated. NOT an IP address and not '
  'reversible: it exists so repeated submissions from one source can be '
  'correlated during review. Keyed by SCORE_SECRET, so rotating that secret '
  'deliberately breaks correlation with older rows.';

-- "Has this exact score already come from this source for this game recently?"
create index if not exists scores_dupe_probe_idx
  on public.scores (slug, ip_tag, score);

-- The admin review screen and the duplicate probe both read these columns with
-- the service key only. Public reads still go through the existing
-- "Public can read visible scores" policy, which is unchanged and continues to
-- expose status='ok' rows only — flag_evidence and ip_tag are on rows that
-- policy already refuses to return.


-- ============================================================================
-- >>> feedback.sql
-- ============================================================================
-- db/feedback.sql — user feedback.
--
-- Earlier files are left untouched on purpose: they are the applied history of
-- this database, and rewriting history so it never mentions scores would make a
-- replay from scratch diverge from what production actually did.
--
-- ── Part 1: the leaderboard retirement, undone ─────────────────────────────

-- RETIREMENT REVERSED. The leaderboard is back in the application (lib/scores.mjs,
-- GET/POST /api/scores, /leaderboard), so this file no longer drops the table it
-- reads. The drops are kept below, commented, because they DID run against
-- production once and a reader of this file needs to know that -- deleting the
-- lines outright would make the applied history unexplainable.
--
--   drop function if exists public.submit_score(text, text, integer, text);
--   drop function if exists public.submit_score(text, text, integer);
--   drop function if exists public.prune_scores(integer);
--   drop view     if exists public.scores_public;
--   drop table    if exists public.scores;
--
-- Because Supabase tracks migrations by FILENAME, editing this file does not
-- un-drop anything on a database where it already ran. That is what
-- db/scores-restore.sql is for: a forward migration that re-creates the table.
-- A replay from scratch now keeps the table all the way through.

-- ── Part 2: feedback ───────────────────────────────────────────────────────
-- Private by construction. Feedback is not a public wall: people report bugs,
-- mention what they were doing, and sometimes leave contact details. Read
-- access is admin-only via the secret key, which bypasses RLS. The publishable
-- key that ships in the browser can INSERT and nothing else.

create table if not exists public.feedback (
  id          bigint generated always as identity primary key,
  created_at  timestamptz  not null default now(),
  -- What the person said. Bounded in the database as well as the API, so a
  -- direct PostgREST insert cannot store a megabyte of text.
  message     text         not null check (length(btrim(message)) between 4 and 2000),
  -- Optional. Empty string is normalised to NULL by the API so "no email" has
  -- one representation rather than two.
  email       text         check (email is null or length(email) <= 200),
  -- Where they were when they sent it — the single most useful field for
  -- reproducing a bug, and the one people always forget to include.
  page        text         check (page is null or length(page) <= 300),
  -- 'bug' | 'idea' | 'other'. Kept as text with a check rather than an enum so
  -- adding a kind later is a one-line migration, not a type alteration.
  kind        text         not null default 'other'
                           check (kind in ('bug', 'idea', 'other')),
  -- Moderation lifecycle. Archived rows stay for the record; deletion is a
  -- separate, deliberate act in the admin UI.
  status      text         not null default 'new'
                           check (status in ('new', 'read', 'archived')),
  -- Salted hash, never a raw address. Enough to spot one person filing forty
  -- submissions; useless for identifying them.
  ip_hash     text         check (ip_hash is null or length(ip_hash) <= 64),
  user_agent  text         check (user_agent is null or length(user_agent) <= 300)
);

-- The review queue reads "newest first, optionally filtered by status", which is
-- exactly this index. Without it every dashboard load is a sequential scan.
create index if not exists feedback_status_created_idx
  on public.feedback (status, created_at desc);

-- Spam triage: "how many did this source send recently?" One partial index
-- rather than one on the whole table, since only recent rows are ever asked about.
create index if not exists feedback_ip_recent_idx
  on public.feedback (ip_hash, created_at desc)
  where ip_hash is not null;

alter table public.feedback enable row level security;

-- Deny-by-default plus ONE permissive policy: anonymous insert. There is
-- deliberately no select policy, so the publishable key cannot read back a
-- single row — not even the one it just wrote.
drop policy if exists "Anyone may send feedback" on public.feedback;
create policy "Anyone may send feedback"
  on public.feedback for insert
  to anon, authenticated
  with check (true);

drop policy if exists "Feedback is never publicly readable" on public.feedback;

revoke all on public.feedback from anon, authenticated;
grant insert on public.feedback to anon, authenticated;

comment on table public.feedback is
  'User-submitted feedback. Insert-only for anon; readable only via the secret key. Never expose through a public view.';

-- ── Part 3: retention ──────────────────────────────────────────────────────
-- The admin security tables grow forever and are only ever read for the last
-- ~50 rows. Left alone they become the largest tables in the database, made
-- entirely of records nobody will look at again.
--
-- The audit trail is deliberately kept LONGER than the rest and is never
-- touched by anything the dashboard can call: it is the record of what
-- administrators did, and a log that operators can shorten is not evidence.

create or replace function public.prune_admin_logs(
  attempts_days integer default 30,
  events_days   integer default 90,
  audit_days    integer default 365
)
returns table (attempts_deleted bigint, events_deleted bigint, audit_deleted bigint)
language plpgsql
security definer
set search_path = public
as $$
declare a bigint; e bigint; d bigint;
begin
  delete from public.admin_login_attempts
    where at < now() - make_interval(days => greatest(attempts_days, 7));
  get diagnostics a = row_count;

  delete from public.admin_security_events
    where at < now() - make_interval(days => greatest(events_days, 30));
  get diagnostics e = row_count;

  -- Floor of one year. A caller passing 0 must not be able to erase the trail.
  delete from public.admin_audit_logs
    where at < now() - make_interval(days => greatest(audit_days, 365));
  get diagnostics d = row_count;

  -- Expired and revoked sessions are pure garbage once they can no longer
  -- authenticate anything.
  delete from public.admin_sessions
    where expires_at < now() - interval '7 days'
       or (revoked_at is not null and revoked_at < now() - interval '7 days');

  return query select a, e, d;
end;
$$;

revoke all on function public.prune_admin_logs(integer, integer, integer) from public, anon, authenticated;

comment on function public.prune_admin_logs is
  'Retention sweep for the admin tables. SECURITY DEFINER and revoked from anon/authenticated: only the service key may call it.';

-- Orphaned play counters: rows for games that no longer exist in the catalog.
-- game_stats is written by slug with no foreign key (the catalog is refreshed
-- wholesale, and a hard FK would make a refresh fail rather than a counter go
-- stale), so orphans accumulate silently every time a game is delisted.
create or replace function public.prune_orphan_game_stats()
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare n bigint;
begin
  delete from public.game_stats gs
   where not exists (select 1 from public.games g where g.slug = gs.slug);
  get diagnostics n = row_count;
  return n;
end;
$$;

revoke all on function public.prune_orphan_game_stats() from public, anon, authenticated;

comment on function public.prune_orphan_game_stats is
  'Deletes game_stats rows whose slug is no longer in games. No FK exists by design — a wholesale catalog refresh must not fail on one counter.';


-- ============================================================================
-- >>> scores-restore.sql
-- ============================================================================
-- =====================================================================
-- ZoFHub · restore the leaderboard   (run ONCE in the Supabase SQL editor)
-- =====================================================================
-- WHY THIS FILE EXISTS AS ITS OWN MIGRATION.
--
-- db/community.sql creates public.scores. db/feedback.sql then dropped it --
-- the leaderboard was deliberately retired, and the drop ran against
-- production. Supabase tracks migrations by FILENAME, so editing feedback.sql
-- after the fact un-drops nothing on a database where it already ran. The only
-- correct fix for a live database is a new forward migration, which is this.
--
-- SAFE AND RE-RUNNABLE. Everything is IF NOT EXISTS / OR REPLACE. On a database
-- where the table survived, this changes nothing; on one where it was dropped,
-- it comes back with the same shape, indexes and policy the application expects.
--
--   Dashboard -> SQL Editor -> New query -> paste this file -> Run.
--
-- The application degrades gracefully until then: GET /api/scores answers with
-- available:false and an empty board, and submissions are refused with a plain
-- message rather than a 500.
-- =====================================================================

create table if not exists public.scores (
  id          bigint generated by default as identity primary key,
  slug        text         not null,
  player_name varchar(40)  not null default 'Player',
  score       bigint       not null default 0,
  status      text         not null default 'ok',   -- 'ok' = visible, 'flagged' = quarantined outlier
  flag_reason text,
  created_at  timestamptz  not null default now()
);

-- Re-add the moderation columns for the case where an OLD scores table (from
-- before db/community-scores-integrity.sql) is what survived.
alter table public.scores add column if not exists status      text not null default 'ok';
alter table public.scores add column if not exists flag_reason text;

comment on table public.scores is
  'Player-reported leaderboard scores per game slug. status=ok is public; flagged rows are held for review. Written only by the Node server, which enforces single-use proof-of-play tokens and score ceilings (lib/scores.mjs).';

-- Read paths the server actually uses.
create index if not exists scores_slug_score_idx   on public.scores (slug, score desc);
create index if not exists scores_score_idx        on public.scores (score desc);
create index if not exists scores_slug_player_idx  on public.scores (slug, player_name);
create index if not exists scores_status_score_idx on public.scores (status, score desc);

-- One row per player per game: the server does keep-best by updating in place,
-- and without this constraint a race between two submissions could leave two.
create unique index if not exists scores_slug_player_uniq
  on public.scores (slug, player_name);

-- RLS: the publishable key that ships in the browser may read VISIBLE rows and
-- nothing else. It must never write -- every insert goes through the Node
-- server with the secret key, which is where the anti-cheat rules live. A
-- browser that could insert directly would bypass all of them.
alter table public.scores enable row level security;
drop policy if exists "Public can read scores"         on public.scores;
drop policy if exists "Public can read visible scores" on public.scores;
create policy "Public can read visible scores"
  on public.scores for select using (status = 'ok');

-- Keep the table BOUNDED. Flagged rows older than 7 days are purged (nobody is
-- going to review a fortnight-old outlier), and only the top N visible scores
-- per game are kept.
create or replace function public.prune_scores(keep_per_game integer default 200)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  removed integer := 0;
  n integer;
begin
  delete from public.scores
   where status = 'flagged' and created_at < now() - interval '7 days';
  get diagnostics n = row_count;
  removed := removed + n;

  with ranked as (
    select id, row_number() over (partition by slug order by score desc, created_at asc) as rn
      from public.scores
     where status = 'ok'
  )
  delete from public.scores s
   using ranked r
   where s.id = r.id and r.rn > keep_per_game;
  get diagnostics n = row_count;
  removed := removed + n;

  return removed;
end;
$$;

revoke all on function public.prune_scores(integer) from public, anon, authenticated;


-- ============================================================================
-- >>> 14_subscriber_emails.sql
-- ============================================================================
-- =====================================================================
-- ZoFHub · subscriber_emails   (run ONCE in the Supabase SQL editor)
-- =====================================================================
-- CENSORSHIP INSURANCE. If this domain is blocked, the only way to tell
-- anyone where the mirror is, is to already have a way to reach them.
-- That is the entire purpose of this table and it is why it holds so little.
--
-- TWO COLUMNS, ON PURPOSE. No IP, no user agent, no signup timestamp, no
-- referrer, no confirmation state. The homepage promises "no accounts, zero
-- tracking", and a schema is the only place that promise can actually be kept:
-- a column that does not exist cannot be logged, joined, correlated or
-- subpoenaed. Anything added here later makes that sentence a lie, so it should
-- not be added here later.
--
-- A WRITE-ONLY VAULT. RLS is deny-by-default and the public (anon) key is
-- granted INSERT and nothing else. A browser can drop an address in; a browser
-- cannot read one back, cannot enumerate, cannot count, and cannot amend. Even
-- with the publishable key in hand — and it ships to every visitor, by design —
-- there is no query that returns somebody else's address. The server reads this
-- table with the secret key, which bypasses RLS, and that key never leaves the
-- backend.
--
--   Dashboard -> SQL Editor -> New query -> paste -> Run.
-- =====================================================================

create table if not exists public.subscriber_emails (
  id    uuid primary key default gen_random_uuid(),
  email text not null
);

comment on table public.subscriber_emails is
  'Mirror-update list. Deliberately two columns: no IP, no timestamp, no consent log — the homepage promises zero tracking and this schema is what keeps that true. Write-only to the anon key.';

-- One row per address. Without this, the insert endpoint is a free way to grow
-- the table without bound by resubmitting the same address.
-- Case-insensitive: Foo@x.com and foo@x.com are one person.
create unique index if not exists subscriber_emails_lower_email_uniq
  on public.subscriber_emails (lower(email));

-- ── Row-Level Security: deny by default ──────────────────────────────────
alter table public.subscriber_emails enable row level security;
alter table public.subscriber_emails force row level security;

-- Clear any earlier policy so re-running this file is safe and the final
-- posture is exactly what is written below, not whatever accumulated.
drop policy if exists "anon can insert a subscriber email" on public.subscriber_emails;
drop policy if exists "public can read subscribers"        on public.subscriber_emails;

-- INSERT only. There is deliberately NO select, update or delete policy, so
-- every other operation is refused by RLS for anon and authenticated alike.
create policy "anon can insert a subscriber email"
  on public.subscriber_emails
  for insert
  to anon, authenticated
  with check (
    -- Enforced in the database as well as the server: a shape check here still
    -- applies to a direct PostgREST insert that never touched our Express route.
    email is not null
    and length(email) between 6 and 254
    and position('@' in email) > 1
  );

-- ── Grants ───────────────────────────────────────────────────────────────
-- RLS decides WHICH rows; grants decide WHICH VERBS. Both have to say yes, so
-- the verbs are narrowed here too rather than relying on policies alone.
revoke all on table public.subscriber_emails from anon, authenticated;
grant insert on table public.subscriber_emails to anon, authenticated;
grant all    on table public.subscriber_emails to service_role;

-- A sequence grant is not needed: the primary key is a uuid default, not a
-- serial, so an inserting role never touches a sequence.


-- ============================================================================
-- >>> 15_ai_feedback.sql
-- ============================================================================
-- =====================================================================
-- ZoFHub · ai_feedback   (run ONCE in the Supabase SQL editor)
-- =====================================================================
-- Feedback on AI answers, shaped so it can improve the system WITHOUT
-- becoming a pipe from "anyone can type" to "model weights".
--
-- WHAT THIS IS NOT. It is not a conversation log. The AI runs entirely in
-- the visitor's browser (public/js/ai.js talks to providers directly), and
-- this server never sees a chat. A row appears here only when somebody
-- deliberately rates, corrects or reports ONE answer. There is no column
-- for a conversation id, and adding one would turn a feedback table into
-- surveillance of a feature whose whole design is that we cannot see it.
--
-- CONSENT IS PER ROW, NOT PER USER. `consent_training` records what the
-- person agreed to for THIS submission. The default is false, and false
-- means the row may be counted and evaluated but may never enter a
-- training set. lib/ai-feedback.mjs enforces the same rule in code; this
-- is the copy that survives a bug in the application.
--
-- REDACTED ON ARRIVAL. The API redacts emails, phone numbers, card-shaped
-- digits, API tokens, street addresses and IPs BEFORE insert. There is
-- deliberately no column holding the original text: a raw copy would
-- outlive the redaction in backups and replicas.
--
--   Dashboard -> SQL Editor -> New query -> paste -> Run.
-- =====================================================================

create table if not exists public.ai_feedback (
  id           uuid primary key default gen_random_uuid(),
  created_at   timestamptz not null default now(),

  -- One of: rating | correction | regenerate | accepted | report | delivery_failure
  type         text not null check (type in
                 ('rating','correction','regenerate','accepted','report','delivery_failure')),

  -- Redacted text. Bounded here as well as in the API so a direct PostgREST
  -- insert cannot store an essay.
  input        text check (input is null or length(input) <= 4000),
  output       text check (output is null or length(output) <= 4000),
  correction   text check (correction is null or length(correction) <= 4000),
  rating       smallint check (rating is null or rating in (-1, 0, 1)),

  -- PROVENANCE. Which backend and model produced the answer being judged, and
  -- which system-prompt version was in force. Without these a row is unusable:
  -- you cannot tell whether a complaint is about Llama, about Pollinations, or
  -- about a prompt that has since been rewritten.
  provider       text check (provider is null or length(provider) <= 40),
  model          text check (model is null or length(model) <= 120),
  prompt_version text check (prompt_version is null or length(prompt_version) <= 40),

  -- The routing decision from lib/ai-feedback.mjs, stored so a curator can see
  -- why a row landed where it did rather than re-deriving it months later.
  lanes        text[] not null default '{}',
  route_reason text check (route_reason is null or length(route_reason) <= 300),

  -- Consent, and the derived verdict. training_eligible is false unless the
  -- person opted in AND the signal type is one that can carry a training target.
  consent_training  boolean not null default false,
  training_eligible boolean not null default false,

  -- How many redactions fired. A high count is a signal that someone pasted
  -- something personal, and curation should treat the row with suspicion.
  redactions   integer not null default 0,

  -- Curation state. A row is never used for anything until a human moves it.
  --   pending  -> untouched
  --   approved -> may enter a curated dataset
  --   rejected -> excluded permanently
  review_state text not null default 'pending'
                 check (review_state in ('pending','approved','rejected')),

  -- RETENTION. Set on insert by the API. prune_ai_feedback() deletes past it,
  -- so "we keep this for N days" is enforced by a job rather than by intention.
  expires_at   timestamptz not null default (now() + interval '180 days')
);

comment on table public.ai_feedback is
  'Feedback on individual AI answers. Redacted before insert, consent recorded per row, never a conversation log. Training use requires consent_training AND human approval.';

-- Curation reads filter on these three constantly.
create index if not exists ai_feedback_state_idx on public.ai_feedback (review_state, created_at desc);
create index if not exists ai_feedback_training_idx on public.ai_feedback (training_eligible, review_state);
create index if not exists ai_feedback_expiry_idx on public.ai_feedback (expires_at);

-- ── Row-Level Security: deny by default ──────────────────────────────────
alter table public.ai_feedback enable row level security;
alter table public.ai_feedback force row level security;

drop policy if exists "anon can submit ai feedback" on public.ai_feedback;
drop policy if exists "public can read ai feedback"  on public.ai_feedback;

-- INSERT only, and only the shapes the application produces. There is
-- deliberately NO select/update/delete policy: a browser can leave feedback and
-- can never read anyone's back. The server reads with the secret key, which
-- bypasses RLS and never leaves the backend.
create policy "anon can submit ai feedback"
  on public.ai_feedback
  for insert
  to anon, authenticated
  with check (
    type in ('rating','correction','regenerate','accepted','report','delivery_failure')
    and coalesce(length(input), 0) <= 4000
    and coalesce(length(output), 0) <= 4000
    and coalesce(length(correction), 0) <= 4000
    -- A client may NOT declare itself training-eligible. That verdict is the
    -- server's, and pinning it here means a forged PostgREST insert cannot
    -- smuggle a row into the training pool.
    and training_eligible = false
    and review_state = 'pending'
  );

revoke all on table public.ai_feedback from anon, authenticated;
grant insert on table public.ai_feedback to anon, authenticated;
grant all    on table public.ai_feedback to service_role;

-- ── Retention ────────────────────────────────────────────────────────────
-- Approved rows are exempt: they have been reviewed and belong to a dataset
-- whose provenance would break if rows vanished underneath it. Everything else
-- is deleted on schedule, including rows nobody ever looked at.
create or replace function public.prune_ai_feedback()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  removed integer;
begin
  delete from public.ai_feedback
   where expires_at < now()
     and review_state <> 'approved';
  get diagnostics removed = row_count;
  return removed;
end;
$$;

revoke all on function public.prune_ai_feedback() from public, anon, authenticated;
grant execute on function public.prune_ai_feedback() to service_role;

-- ── Right to erasure ─────────────────────────────────────────────────────
-- There is no user id to key on, by design. So deletion is offered the only
-- honest way it can be: by the exact text somebody submitted, which they are
-- the only person likely to still have.
create or replace function public.forget_ai_feedback(p_text text)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  removed integer;
begin
  if p_text is null or length(btrim(p_text)) < 12 then
    return 0;   -- refuse to mass-delete on a short string
  end if;
  delete from public.ai_feedback
   where input = p_text or output = p_text or correction = p_text;
  get diagnostics removed = row_count;
  return removed;
end;
$$;

revoke all on function public.forget_ai_feedback(text) from public, anon, authenticated;
grant execute on function public.forget_ai_feedback(text) to service_role;


-- ============================================================================
-- >>> control-plane.sql
-- ============================================================================
-- =====================================================================
-- ZoFHub · control plane   (run ONCE in the Supabase SQL editor, or let the
--                           GitHub integration apply supabase/migrations/)
-- =====================================================================
-- The storage behind the admin control centre: staff accounts, a real content
-- lifecycle for games, providers, categories and tags, typed site settings, and
-- the approved-target model that governs the proxy.
--
-- DESIGN RULES THIS FILE FOLLOWS
--
--   1. SERVER-ONLY, FAIL CLOSED. Every table created here has RLS enabled and
--      NO policy, and the public roles are explicitly revoked. The publishable
--      key that ships to browsers can read none of it; only the Node server,
--      holding the secret key, can. That is stated here rather than left to
--      grants.sql, because on a database where grants.sql already ran this
--      file is applied AFTER it and would otherwise inherit Supabase's default
--      "anon may do anything RLS allows" privileges.
--
--   2. THE DATABASE ENFORCES INTEGRITY, NOT JUST THE APP. Status values are
--      CHECK constraints, categories are a foreign key, provider references are
--      a foreign key with ON DELETE RESTRICT, and a category that still holds
--      games cannot be deleted. Application validation sits in front of these;
--      it does not replace them.
--
--   3. NOTHING HERE DESTROYS DATA. Existing games default to `published`, so the
--      public catalog is unchanged the moment this runs. Backfills only fill
--      columns that are NULL.
--
--   4. NO REDUNDANT TABLES. Proxy sessions and health are deliberately NOT
--      tables: a per-tunnel session row is a browsing record of an anonymous
--      visitor, and keeping it would contradict the privacy model. They live in
--      server memory with a bounded history. Proxy audit events go to the
--      existing admin_audit_logs rather than a parallel log.
--
-- Idempotent: every CREATE is guarded, every constraint is added inside an
-- exception handler, and re-running the file is a no-op.
-- =====================================================================


-- ── 1. Staff accounts ─────────────────────────────────────────────────────
-- ZoFHub has no public user accounts, and this does not add any: visitors are
-- anonymous by design. These are STAFF — the people who run the site. The
-- owner configured in the environment (ADMIN_USERNAME / ADMIN_PASSWORD_HASH)
-- remains the break-glass account and is deliberately NOT a row here, so no
-- database edit and no admin screen can lock the owner out or demote them.
create table if not exists public.admin_users (
  id                   uuid primary key default gen_random_uuid(),
  username             text        not null,
  display_name         text,
  role                 text        not null,
  status               text        not null default 'active',
  -- scrypt$N$r$p$salt$hash — the same versioned format as ADMIN_PASSWORD_HASH.
  -- NULL once an account is deleted: a deleted account can never log in again.
  password_hash        text,
  must_change_password boolean     not null default true,
  status_reason        text,
  created_at           timestamptz not null default now(),
  created_by           text        not null,
  updated_at           timestamptz not null default now(),
  updated_by           text,
  last_login_at        timestamptz,
  deleted_at           timestamptz
);

do $$ begin
  alter table public.admin_users add constraint admin_users_role_check
    check (role in ('super_admin', 'admin', 'content_manager', 'moderator', 'analyst', 'support'));
exception when duplicate_object then null; end $$;
do $$ begin
  alter table public.admin_users add constraint admin_users_status_check
    check (status in ('active', 'suspended', 'deactivated', 'deleted'));
exception when duplicate_object then null; end $$;
do $$ begin
  alter table public.admin_users add constraint admin_users_username_check
    check (username ~ '^[a-z0-9][a-z0-9._-]{2,39}$');
exception when duplicate_object then null; end $$;
-- A deleted account keeps its username RESERVED. The audit trail records who did
-- what by username, and letting a new account reuse a deleted one's name would
-- make every historical entry ambiguous.
create unique index if not exists admin_users_username_uidx on public.admin_users (lower(username));
create index if not exists admin_users_status_idx on public.admin_users (status, role);

comment on table public.admin_users is
  'Staff accounts for the admin console. Not visitors — ZoFHub has no public accounts. The environment-configured owner is intentionally not a row here.';

-- Sessions learn which staff account they belong to. NULL = the environment
-- owner. ON DELETE CASCADE is safe because accounts are soft-deleted in normal
-- operation; a hard delete of the row should take its sessions with it.
alter table public.admin_sessions add column if not exists user_id   uuid references public.admin_users (id) on delete cascade;
-- When the holder last re-entered their password. Destructive actions require
-- this to be recent, so a stolen-but-idle session cannot delete anything.
alter table public.admin_sessions add column if not exists reauth_at timestamptz;
create index if not exists admin_sessions_user_idx on public.admin_sessions (user_id) where revoked_at is null;


-- ── 2. The audit trail learns structure, and becomes tamper-evident ────────
-- The existing table is append-only (a trigger refuses UPDATE and DELETE). What
-- it lacked was structure to answer "everything that happened to game 4421"
-- without string-matching a free-text target, and any way to DETECT a row that
-- was inserted out of band or rewritten by someone who disabled the trigger.
alter table public.admin_audit_logs add column if not exists actor_id      uuid;
alter table public.admin_audit_logs add column if not exists actor_role    text;
alter table public.admin_audit_logs add column if not exists resource_type text;
alter table public.admin_audit_logs add column if not exists resource_id   text;
alter table public.admin_audit_logs add column if not exists request_id    text;
alter table public.admin_audit_logs add column if not exists prev_hash     text;
alter table public.admin_audit_logs add column if not exists row_hash      text;

create index if not exists admin_audit_resource_idx on public.admin_audit_logs (resource_type, resource_id, id desc);
create index if not exists admin_audit_actor_idx    on public.admin_audit_logs (actor_id, id desc);

-- Hash chain. Each new row stores sha256(previous row_hash | its own fields).
-- Rewriting or removing a chained row breaks every hash after it, which
-- admin_audit_verify() below reports. The advisory lock serialises appends so
-- two concurrent inserts cannot both chain onto the same predecessor.
create or replace function public.admin_audit_chain()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  prev text;
begin
  perform pg_advisory_xact_lock(7340031);
  select l.row_hash into prev
    from public.admin_audit_logs l
   where l.row_hash is not null
   order by l.id desc
   limit 1;
  new.prev_hash := prev;
  new.row_hash := encode(sha256(convert_to(concat_ws('|',
      coalesce(prev, ''), new.id::text,
      to_char(new.at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'),
      coalesce(new.username, ''), new.action, coalesce(new.target, ''), new.outcome,
      coalesce(new.actor_id::text, ''), coalesce(new.actor_role, ''),
      coalesce(new.resource_type, ''), coalesce(new.resource_id, ''),
      coalesce(new.detail::text, '')), 'UTF8')), 'hex');
  return new;
end $$;

drop trigger if exists trg_admin_audit_chain on public.admin_audit_logs;
create trigger trg_admin_audit_chain
  before insert on public.admin_audit_logs
  for each row execute function public.admin_audit_chain();

-- Re-derive the newest p_limit chained rows and report the first one whose
-- stored hash does not match its contents or whose link to its predecessor is
-- broken. The oldest row in the window is the anchor: its predecessor may have
-- aged out through retention, which is not tampering.
create or replace function public.admin_audit_verify(p_limit integer default 1000)
returns table (checked integer, first_bad_id bigint)
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  r record;
  expected text;
  last_hash text := null;
  n integer := 0;
  lim integer := least(greatest(coalesce(p_limit, 1000), 1), 100000);
begin
  first_bad_id := null;
  for r in
    select * from (
      select * from public.admin_audit_logs
       where row_hash is not null
       order by id desc
       limit lim
    ) w order by w.id asc
  loop
    expected := encode(sha256(convert_to(concat_ws('|',
        coalesce(r.prev_hash, ''), r.id::text,
        to_char(r.at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'),
        coalesce(r.username, ''), r.action, coalesce(r.target, ''), r.outcome,
        coalesce(r.actor_id::text, ''), coalesce(r.actor_role, ''),
        coalesce(r.resource_type, ''), coalesce(r.resource_id, ''),
        coalesce(r.detail::text, '')), 'UTF8')), 'hex');
    if expected is distinct from r.row_hash
       or (n > 0 and r.prev_hash is distinct from last_hash) then
      first_bad_id := r.id;
      checked := n + 1;
      return next;
      return;
    end if;
    last_hash := r.row_hash;
    n := n + 1;
  end loop;
  checked := n;
  return next;
end $$;


-- ── 3. Game providers ─────────────────────────────────────────────────────
-- The auditable chain the admin console enforces:
--     game → provider → approved origin → embedding policy
-- A game may only be created or re-pointed at an embed URL whose origin this
-- provider lists, and only while the provider is `approved`. A `suspended` or
-- `revoked` provider's games are withheld from the public catalog.
create table if not exists public.game_providers (
  id             text primary key,
  name           text        not null,
  status         text        not null default 'pending',
  embed_origins  text[]      not null default '{}',
  asset_origins  text[]      not null default '{}',
  -- direct: the visitor's browser frames the provider itself (required for the
  -- SDK-based distributors). proxied: framed through this site's /embed route.
  embed_mode     text        not null default 'direct',
  -- NULL = no sandbox attribute. Adding one to a third-party game is a
  -- behaviour change that has to be revalidated per provider, so it is opt-in.
  sandbox_policy text,
  allow_features text[]      not null default '{}',
  terms_url      text,
  license_basis  text,
  notes          text,
  reviewed_at    timestamptz,
  reviewed_by    text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  updated_by     text
);

do $$ begin
  alter table public.game_providers add constraint game_providers_id_check
    check (id ~ '^[a-z0-9][a-z0-9-]{1,39}$');
exception when duplicate_object then null; end $$;
do $$ begin
  alter table public.game_providers add constraint game_providers_status_check
    check (status in ('approved', 'restricted', 'pending', 'suspended', 'revoked'));
exception when duplicate_object then null; end $$;
do $$ begin
  alter table public.game_providers add constraint game_providers_embed_mode_check
    check (embed_mode in ('direct', 'proxied'));
exception when duplicate_object then null; end $$;

-- Seeded from the licensing audit (tools/audit-licensing.mjs), not invented:
--   SAFE       → approved     ACCOUNT / GRAY → restricted (existing games keep
--   PARTNER-ID → suspended                     serving; no new ones)
-- ON CONFLICT DO NOTHING: an operator's later decision is never overwritten.
insert into public.game_providers
  (id, name, status, embed_origins, asset_origins, embed_mode, terms_url, license_basis, notes, reviewed_by)
values
  ('gamedistribution', 'GameDistribution', 'approved',
   '{https://html5.gamedistribution.com}', '{https://img.gamedistribution.com}', 'direct',
   'https://gamedistribution.com/publishers/partnership/',
   'Distributes its catalog to third-party portals at no cost through its official feed. Games must run unmodified in GameDistribution''s own iframe with its SDK and ads intact.',
   'Seeded from the licensing audit (tier SAFE).', 'migration'),
  ('gamemonetize', 'GameMonetize', 'approved',
   '{https://html5.gamemonetize.co,https://html5.gamemonetize.com}', '{https://img.gamemonetize.com}', 'direct',
   'https://gamemonetize.com/',
   'Licensed for third-party embedding through its own iframe and SDK.',
   'Seeded from the licensing audit (tier SAFE).', 'migration'),
  ('y8', 'Y8 (embed directory)', 'approved',
   '{https://www.y8.com,https://y8.com}', '{https://cdn.y8.com,https://cdn2.y8.com,https://img.y8.com}', 'proxied',
   'https://www.y8.com/games_for_your_website',
   'Y8''s own "Games for your website" embed directory.',
   'Seeded from the licensing audit (tier SAFE).', 'migration'),
  ('onlinegames', 'OnlineGames.io', 'restricted',
   '{https://www.onlinegames.io,https://cloud.onlinegames.io}', '{https://www.onlinegames.io}', 'direct',
   null, 'Permits embedding via its own codes; hotlink-protected.',
   'Tier GRAY: existing canonical titles keep serving; no new games until verified.', 'migration'),
  ('htmlgames', 'HTMLGames', 'restricted',
   '{https://cdn.htmlgames.com,https://www.htmlgames.com}', '{https://cdn.htmlgames.com,https://www.htmlgames.com}', 'proxied',
   null, 'Free to embed only through its official embed programme.',
   'Tier ACCOUNT: needs a publisher account before new games are added.', 'migration'),
  ('famobi', 'Famobi', 'restricted',
   '{https://play.famobi.com}', '{https://img.cdn.famobi.com}', 'proxied',
   null, 'Free to embed through a publisher account and its feed.',
   'Tier ACCOUNT: needs a publisher account before new games are added.', 'migration'),
  ('gameflare', 'GameFlare', 'restricted',
   '{https://distribution.gameflare.com}', '{https://data.gameflare.com}', 'direct',
   null, 'Requires GameFlare''s distribution programme.',
   'Tier ACCOUNT: needs a publisher account before new games are added.', 'migration'),
  ('gamezop', 'Gamezop', 'suspended',
   '{}', '{https://static.gamezop.com}', 'direct',
   null, 'Embeds carry ANOTHER publisher''s partner id — not licensed to this site.',
   'Tier PARTNER-ID: withheld until the site has its own partner id.', 'migration')
on conflict (id) do nothing;


-- ── 4. Categories and tags ────────────────────────────────────────────────
create table if not exists public.game_categories (
  slug        text primary key,
  label       text        not null,
  description text,
  parent_slug text references public.game_categories (slug) on update cascade on delete restrict,
  sort_order  integer     not null default 0,
  visible     boolean     not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  updated_by  text
);

-- Legacy keys are free-form ("puzzle games", "2048 & merge") and the public
-- category URLs are built from them, so they are accepted as they are. The admin
-- console only ever CREATES strict slugs; this constraint just keeps the column
-- lowercase and bounded.
do $$ begin
  alter table public.game_categories add constraint game_categories_slug_check
    check (slug = lower(slug) and char_length(slug) between 1 and 40 and slug !~ '[\r\n\t]');
exception when duplicate_object then null; end $$;
do $$ begin
  alter table public.game_categories add constraint game_categories_label_check
    check (char_length(label) between 1 and 60);
exception when duplicate_object then null; end $$;

insert into public.game_categories (slug, label)
select distinct g.category, initcap(replace(g.category, '-', ' '))
  from public.games g
 where g.category = lower(g.category) and char_length(g.category) between 1 and 40
on conflict (slug) do nothing;
insert into public.game_categories (slug, label) values ('arcade', 'Arcade')
on conflict (slug) do nothing;

-- The foreign key. Added NOT VALID so a row with an unusual legacy value can
-- never make this migration fail, then validated when every row conforms — which
-- the seed above guarantees for any lowercase value.
do $$ begin
  alter table public.games add constraint games_category_fk
    foreign key (category) references public.game_categories (slug)
    on update cascade on delete restrict not valid;
exception when duplicate_object then null; end $$;
do $$ begin
  if not exists (
    select 1 from public.games g
     where not exists (select 1 from public.game_categories c where c.slug = g.category)
  ) then
    alter table public.games validate constraint games_category_fk;
  end if;
end $$;

create table if not exists public.game_tags (
  slug       text primary key,
  label      text        not null,
  created_at timestamptz not null default now()
);
do $$ begin
  alter table public.game_tags add constraint game_tags_slug_check
    check (slug ~ '^[a-z0-9][a-z0-9-]{0,39}$');
exception when duplicate_object then null; end $$;

create table if not exists public.game_tag_links (
  game_id  bigint not null references public.games (id)      on delete cascade,
  tag_slug text   not null references public.game_tags (slug) on update cascade on delete cascade,
  primary key (game_id, tag_slug)
);
create index if not exists game_tag_links_tag_idx on public.game_tag_links (tag_slug);


-- ── 5. The games table gains a lifecycle ──────────────────────────────────
-- `is_working` stays exactly what it was: the link checker's verdict on whether
-- the embed still loads. `status` is the EDITORIAL state. A game is public only
-- when both say so — a published game that stops loading is hidden by the link
-- checker, and a working game that was never approved is hidden by its status.
alter table public.games add column if not exists status            text     not null default 'published';
alter table public.games add column if not exists provider_id       text     references public.game_providers (id) on update cascade on delete restrict;
alter table public.games add column if not exists external_id       text;
alter table public.games add column if not exists description       text;
alter table public.games add column if not exists short_description text;
alter table public.games add column if not exists publisher         text;
alter table public.games add column if not exists developer         text;
alter table public.games add column if not exists featured          boolean  not null default false;
alter table public.games add column if not exists sort_order        integer  not null default 0;
alter table public.games add column if not exists embed_width       smallint;
alter table public.games add column if not exists embed_height      smallint;
alter table public.games add column if not exists license_review    jsonb;
alter table public.games add column if not exists review_note       text;
alter table public.games add column if not exists created_by        text;
alter table public.games add column if not exists updated_by        text;
alter table public.games add column if not exists published_at      timestamptz;
alter table public.games add column if not exists archived_at       timestamptz;

do $$ begin
  alter table public.games add constraint games_status_check
    check (status in ('draft', 'pending_review', 'approved', 'published', 'unpublished', 'archived', 'rejected'));
exception when duplicate_object then null; end $$;
do $$ begin
  alter table public.games add constraint games_text_len_check
    check (coalesce(char_length(description), 0) <= 4000
       and coalesce(char_length(short_description), 0) <= 280
       and coalesce(char_length(review_note), 0) <= 1000);
exception when duplicate_object then null; end $$;
do $$ begin
  alter table public.games add constraint games_embed_size_check
    check ((embed_width is null or embed_width between 100 and 4096)
       and (embed_height is null or embed_height between 100 and 4096));
exception when duplicate_object then null; end $$;

create index if not exists games_status_id_idx on public.games (status, id desc);
create index if not exists games_provider_idx  on public.games (provider_id, id desc);
create index if not exists games_updated_idx   on public.games (updated_at desc, id desc);
create index if not exists games_featured_idx  on public.games (sort_order, id desc) where featured;
-- One row per provider game. Partial, so the thousands of legacy rows without a
-- provider id are unconstrained.
create unique index if not exists games_provider_external_uidx
  on public.games (provider_id, external_id) where external_id is not null;

-- Backfill provider_id from the embed host. Only NULL rows are touched, so an
-- operator's later reassignment survives a re-run.
update public.games set provider_id = case
    when game_url ~* '^https://html5\.gamedistribution\.com/'                 then 'gamedistribution'
    when game_url ~* '^https://html5\.gamemonetize\.(co|com)/'                then 'gamemonetize'
    when game_url ~* '^https://(www\.)?y8\.com/embed/'                        then 'y8'
    when game_url ~* '^https://(www|cloud)\.onlinegames\.io/'                 then 'onlinegames'
    when game_url ~* '^https://(cdn|www)\.htmlgames\.com/'                    then 'htmlgames'
    when game_url ~* '^https://play\.famobi\.com/'                            then 'famobi'
    when game_url ~* '^https://distribution\.gameflare\.com/'                 then 'gameflare'
    when game_url ~* '^https://[a-z0-9]+\.play\.gamezop\.com/'                then 'gamezop'
  end
 where provider_id is null
   and game_url ~* '^https://(html5\.gamedistribution\.com|html5\.gamemonetize\.(co|com)|(www\.)?y8\.com/embed|(www|cloud)\.onlinegames\.io|(cdn|www)\.htmlgames\.com|play\.famobi\.com|distribution\.gameflare\.com|[a-z0-9]+\.play\.gamezop\.com)/';

-- GameDistribution ids are the 32-hex path segment. Only the OLDEST row per id
-- receives it, so a duplicate already in the table cannot violate the unique
-- index above; the importer then recognises that game instead of re-adding it.
update public.games g
   set external_id = m.gd_id
  from (
    select min(id) as id, lower(substring(game_url from 'gamedistribution\.com/([0-9a-fA-F]{32})')) as gd_id
      from public.games
     where provider_id = 'gamedistribution'
       and game_url ~* 'gamedistribution\.com/[0-9a-f]{32}'
     group by 2
  ) m
 where g.id = m.id and g.external_id is null
   and not exists (
     select 1 from public.games x
      where x.provider_id = 'gamedistribution' and x.external_id = m.gd_id
   );

-- The public read path now requires BOTH verdicts. Without this a draft, a game
-- held for licensing review, or a rejected game would be readable straight from
-- the publishable key, however carefully the server filtered its own queries.
drop policy if exists "Public can read working games" on public.games;
create policy "Public can read working games"
  on public.games for select
  using (is_working = true and status = 'published');

create or replace view public.games_public
with (security_invoker = true) as
  select
    id,
    slug,
    title,
    game_url,
    coalesce(nullif(thumbnail_url, ''), '/default-placeholder.svg') as thumbnail_url,
    category,
    last_checked
  from public.games
  where is_working = true and status = 'published';


-- ── 6. Atomic operations the API cannot express safely ────────────────────
-- A bulk status change must be all-or-nothing. PostgREST offers no multi-
-- statement transaction, so the check-then-write happens inside one function
-- call, which is one transaction: if ANY target is missing or not in an allowed
-- source state, it raises and nothing changes.
create or replace function public.cms_bulk_transition(
  p_ids   bigint[],
  p_to    text,
  p_from  text[],
  p_actor text
)
returns integer
language plpgsql
security invoker
set search_path = ''
as $$
declare
  n integer;
  wanted integer := coalesce(array_length(p_ids, 1), 0);
begin
  if wanted = 0 then return 0; end if;
  if wanted > 500 then
    raise exception 'bulk operations are limited to 500 games (got %)', wanted;
  end if;
  if (select count(distinct x) from unnest(p_ids) x) <> wanted then
    raise exception 'duplicate ids in bulk request';
  end if;
  if (select count(*) from public.games where id = any (p_ids) and status = any (p_from)) <> wanted then
    raise exception 'one or more games are missing or not in an allowed state for %', p_to;
  end if;
  update public.games
     set status       = p_to,
         updated_by   = p_actor,
         published_at = case when p_to = 'published' then now() else published_at end,
         archived_at  = case when p_to = 'archived' then now() when p_to <> 'archived' then null else archived_at end
   where id = any (p_ids);
  get diagnostics n = row_count;
  return n;
end $$;

-- Replace a game's tag set in one transaction, creating unknown tags.
create or replace function public.cms_set_game_tags(p_game_id bigint, p_tags text[])
returns integer
language plpgsql
security invoker
set search_path = ''
as $$
declare
  n integer;
begin
  if coalesce(array_length(p_tags, 1), 0) > 30 then
    raise exception 'a game may carry at most 30 tags';
  end if;
  insert into public.game_tags (slug, label)
  select t, initcap(replace(t, '-', ' ')) from unnest(p_tags) t
  on conflict (slug) do nothing;
  delete from public.game_tag_links where game_id = p_game_id;
  insert into public.game_tag_links (game_id, tag_slug)
  select distinct p_game_id, t from unnest(p_tags) t;
  get diagnostics n = row_count;
  return n;
end $$;

-- One round trip for the dashboard's content summary.
create or replace function public.cms_status_counts()
returns table (status text, games bigint)
language sql
stable
security invoker
set search_path = ''
as $$
  select g.status, count(*) from public.games g group by g.status
$$;


-- ── 7. Typed site settings ────────────────────────────────────────────────
-- The KEYS are defined in code (lib/settings-registry.mjs), each with a type and
-- bounds. This table only stores values. A key the code does not define is
-- ignored on read and refused on write, so this can never become a way to set
-- arbitrary configuration — and nothing stored here is ever executed.
create table if not exists public.site_settings (
  key        text primary key,
  value      jsonb       not null,
  updated_at timestamptz not null default now(),
  updated_by text
);
do $$ begin
  alter table public.site_settings add constraint site_settings_key_check
    check (key ~ '^[a-z][a-z0-9_.]{2,63}$');
exception when duplicate_object then null; end $$;


-- ── 8. Proxy governance ───────────────────────────────────────────────────
-- Engines: Ultraviolet, Scramjet, GUST, AnuraOS. Whether each is served, and
-- operator notes. The engine CODE is not configurable from here — only whether
-- it is offered.
create table if not exists public.proxy_providers (
  id         text primary key,
  enabled    boolean     not null default true,
  notes      text,
  updated_at timestamptz not null default now(),
  updated_by text
);
do $$ begin
  alter table public.proxy_providers add constraint proxy_providers_id_check
    check (id ~ '^[a-z0-9][a-z0-9-]{1,39}$');
exception when duplicate_object then null; end $$;

-- Approved destinations. The tunnel may open a connection ONLY to a host that
-- matches an `approved`, unexpired row here, on one of that row's ports. There
-- is no wildcard-everything pattern: the CHECK below requires at least two DNS
-- labels, and the application additionally refuses public-suffix wildcards
-- such as *.co.uk.
create table if not exists public.proxy_targets (
  id          bigint generated by default as identity primary key,
  pattern     text        not null,
  ports       integer[]   not null default '{443}',
  status      text        not null default 'pending',
  purpose     text        not null,
  owner       text,
  expires_at  timestamptz,
  approved_by text,
  approved_at timestamptz,
  created_by  text        not null,
  created_at  timestamptz not null default now(),
  updated_by  text,
  updated_at  timestamptz not null default now()
);
do $$ begin
  alter table public.proxy_targets add constraint proxy_targets_pattern_check
    check (pattern ~ '^(\*\.)?[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$'
       and pattern !~ '^(\*\.)?[0-9.]+$'            -- a destination names a site, never an address
       and char_length(pattern) <= 253);
exception when duplicate_object then null; end $$;
do $$ begin
  alter table public.proxy_targets add constraint proxy_targets_status_check
    check (status in ('pending', 'approved', 'revoked'));
exception when duplicate_object then null; end $$;
do $$ begin
  alter table public.proxy_targets add constraint proxy_targets_ports_check
    check (cardinality(ports) between 1 and 4 and ports <@ array[80, 443, 8080, 8443]);
exception when duplicate_object then null; end $$;
do $$ begin
  alter table public.proxy_targets add constraint proxy_targets_purpose_check
    check (char_length(purpose) between 3 and 300);
exception when duplicate_object then null; end $$;
create unique index if not exists proxy_targets_pattern_uidx on public.proxy_targets (lower(pattern));
create index if not exists proxy_targets_status_idx on public.proxy_targets (status, expires_at);

-- Resource limits and access mode. One row, id 'default'; the application
-- validates every field against hard bounds before it is applied.
create table if not exists public.proxy_policies (
  id         text primary key default 'default',
  policy     jsonb       not null default '{}',
  updated_at timestamptz not null default now(),
  updated_by text
);
do $$ begin
  alter table public.proxy_policies add constraint proxy_policies_single_row
    check (id = 'default');
exception when duplicate_object then null; end $$;


-- ── 9. Every new table is server-only ─────────────────────────────────────
alter table public.admin_users      enable row level security;
alter table public.game_providers   enable row level security;
alter table public.game_categories  enable row level security;
alter table public.game_tags        enable row level security;
alter table public.game_tag_links   enable row level security;
alter table public.site_settings    enable row level security;
alter table public.proxy_providers  enable row level security;
alter table public.proxy_targets    enable row level security;
alter table public.proxy_policies   enable row level security;

do $$
declare
  server_only constant text[] := array[
    'admin_users', 'game_providers', 'game_categories', 'game_tags',
    'game_tag_links', 'site_settings', 'proxy_providers', 'proxy_targets',
    'proxy_policies'
  ];
  rel text;
  grantee_role text;
begin
  foreach rel in array server_only loop
    foreach grantee_role in array array['anon', 'authenticated'] loop
      continue when not exists (select 1 from pg_roles where rolname = grantee_role);
      execute format('revoke all on public.%I from %I', rel, grantee_role);
    end loop;
    if exists (select 1 from pg_roles where rolname = 'service_role') then
      execute format('grant all privileges on public.%I to service_role', rel);
    end if;
  end loop;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant usage, select on all sequences in schema public to service_role';
  end if;
end $$;

-- The functions are the server's, not the public's.
revoke all on function public.cms_bulk_transition(bigint[], text, text[], text) from public;
revoke all on function public.cms_set_game_tags(bigint, text[])                  from public;
revoke all on function public.cms_status_counts()                                from public;
revoke all on function public.admin_audit_verify(integer)                        from public;
do $$
declare
  fn text;
begin
  foreach fn in array array[
    'public.cms_bulk_transition(bigint[], text, text[], text)',
    'public.cms_set_game_tags(bigint, text[])',
    'public.cms_status_counts()',
    'public.admin_audit_verify(integer)'
  ] loop
    if exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('revoke all on function %s from anon', fn);
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
      execute format('revoke all on function %s from authenticated', fn);
    end if;
    if exists (select 1 from pg_roles where rolname = 'service_role') then
      execute format('grant execute on function %s to service_role', fn);
    end if;
  end loop;
end $$;


-- ============================================================================
-- >>> 16_game_telemetry.sql
-- ============================================================================
-- =====================================================================
-- ZoFHub · game_failures + web_vitals   (run ONCE in the Supabase SQL editor)
-- =====================================================================
-- Aggregate quality telemetry. These two tables answer the questions the
-- server genuinely cannot answer on its own:
--
--   1. "Which games are broken, and broken for WHOM?" A game that paints a
--      black screen only on iOS Safari passes the server-side link-check (the
--      URL returns 200) and passes render-verification (it framed fine in
--      headless Chromium). Only a real browser failing to render it knows.
--   2. "Which pages are slow for real visitors on real networks?"
--
-- WHAT THESE TABLES ARE NOT, BY SHAPE AND NOT BY PROMISE
--
-- There is NO VISITOR here. These are counters. The unit of storage is "this
-- combination happened N times", never "this person did this". Look at the
-- columns: there is no id, no ip, no ip_hash, no session, no user agent, no
-- timestamp per event, and no foreign key to anything that identifies anyone.
-- There is deliberately nowhere to PUT such a value, which is a stronger
-- guarantee than a policy saying we would not fill one in.
--
-- The primary keys are the full set of dimensions, so a write is an UPSERT that
-- increments a count. Two different people hitting the same bug on the same
-- browser are INDISTINGUISHABLE: they bump the same row. That is the privacy
-- property, expressed as the schema.
--
-- The key space is small and fixed BY CONSTRUCTION (the check constraints):
--   game_failures : 7 browsers x 2 platforms x 5 kinds = 70 rows per game, max.
--   web_vitals    : 5 metrics x 3 buckets x 6 routes x 2 platforms = 180 rows
--                   for the entire site, forever.
-- A table that cannot exceed 180 rows cannot be re-identified, and cannot grow
-- into a storage problem either.
--
-- The check constraints are not decoration. lib/telemetry.mjs validates the
-- same closed vocabularies in code; these are the copy that survives a bug in
-- the application, and they are what makes free text structurally unable to
-- become a row.
--
-- RLS: deny-by-default. The public anon key can neither read nor write these.
-- Writes arrive through the server with the service-role key (it aggregates in
-- memory and flushes once a minute), and reads are an admin-console concern
-- gated by the `telemetry.read` permission.
--
--   Dashboard -> SQL Editor -> New query -> paste -> Run.
-- =====================================================================

-- ── 1. Game render failures ─────────────────────────────────────────────
create table if not exists public.game_failures (
  slug       text not null,

  -- Server-derived from the request's User-Agent and then DISCARDED. The raw
  -- UA string is never stored; only which of seven families it belongs to.
  browser    text not null check (browser in
               ('chrome','edge','safari','firefox','samsung','opera','other')),

  -- Two values on purpose. Not a device model, not a screen size.
  platform   text not null check (platform in ('desktop','mobile')),

  -- How it failed. Client-supplied, so the API refuses anything not in this
  -- list rather than coercing it — see normalizeFailure() in lib/telemetry.mjs.
  kind       text not null check (kind in
               ('blank','timeout','refused','http_error','script_error')),

  count      bigint not null default 0 check (count >= 0),

  -- Coarse, and about the ROW, not about a visit. `last_seen` is what makes
  -- the data actionable: it separates "broken last March" from "broken now".
  first_seen timestamptz not null default now(),
  last_seen  timestamptz not null default now(),

  primary key (slug, browser, platform, kind)
);

-- "What is broken right now, worst first" — the one query the admin console runs.
create index if not exists game_failures_recent_idx
  on public.game_failures (last_seen desc, count desc);

-- "Is THIS game broken?" — used when reviewing a single game in the CMS.
create index if not exists game_failures_slug_idx
  on public.game_failures (slug);

-- ── 2. Core Web Vitals, bucketed ────────────────────────────────────────
create table if not exists public.web_vitals (
  -- No raw measurement is stored. A value arrives as a number and is reduced to
  -- one of three buckets before it ever reaches this table: an exact LCP of
  -- 2473.84ms is a much stronger identifier than the bucket anyone acts on.
  metric     text not null check (metric in ('LCP','CLS','INP','FCP','TTFB')),
  bucket     text not null check (bucket in ('good','needs_improvement','poor')),

  -- A page CLASS, never a URL. A query string on this site can carry a search
  -- term, so the path is reduced before storage and the query is dropped.
  route      text not null check (route in
               ('home','play','category','ai','browser','other')),

  platform   text not null check (platform in ('desktop','mobile')),

  count      bigint not null default 0 check (count >= 0),
  updated_at timestamptz not null default now(),

  primary key (metric, bucket, route, platform)
);

-- ── 3. Row-level security: deny by default ──────────────────────────────
alter table public.game_failures enable row level security;
alter table public.web_vitals    enable row level security;

-- No policies are created, and that is the point. With RLS on and no policy,
-- PostgREST with the anon key can neither select nor insert. The service-role
-- key bypasses RLS, which is how the server's flush writes. If you later want
-- a public "known issues" page, add a narrow SELECT policy for exactly the
-- columns it needs -- do not grant the anon role write access to a counter,
-- or anyone with the public key can inflate it.

-- ── 4. Atomic increment ─────────────────────────────────────────────────
-- Why a function instead of an upsert from the application: two server
-- instances flushing the same slug at the same moment would each read-then-
-- write and one increment would be lost. `count + excluded.count` inside the
-- database makes the increment atomic, so this is correct with any number of
-- instances -- which matters because the server aggregates in memory and the
-- flush is the only place those numbers become durable.
create or replace function public.bump_game_failure(
  p_slug text, p_browser text, p_platform text, p_kind text, p_n bigint
) returns void
language sql
security definer
set search_path = public
as $$
  insert into public.game_failures (slug, browser, platform, kind, count, last_seen)
  values (p_slug, p_browser, p_platform, p_kind, greatest(p_n, 0), now())
  on conflict (slug, browser, platform, kind) do update
    set count     = public.game_failures.count + greatest(p_n, 0),
        last_seen = now();
$$;

create or replace function public.bump_web_vital(
  p_metric text, p_bucket text, p_route text, p_platform text, p_n bigint
) returns void
language sql
security definer
set search_path = public
as $$
  insert into public.web_vitals (metric, bucket, route, platform, count, updated_at)
  values (p_metric, p_bucket, p_route, p_platform, greatest(p_n, 0), now())
  on conflict (metric, bucket, route, platform) do update
    set count      = public.web_vitals.count + greatest(p_n, 0),
        updated_at = now();
$$;

-- These run as the definer, so make sure the anon role cannot call them
-- directly and bump a counter without going through the server.
revoke all on function public.bump_game_failure(text, text, text, text, bigint) from public, anon;
revoke all on function public.bump_web_vital(text, text, text, text, bigint)    from public, anon;

-- ── 5. Retention: deliberately none ────────────────────────────────────
-- There is no prune function here, and that is a decision rather than an
-- omission. These are COUNTERS, not an event log: game_failures is capped at 70
-- rows per game by its own check constraints and web_vitals at 180 rows for the
-- whole site, forever, so neither can grow into a storage or a privacy problem.
--
-- The real concern -- "a game fixed a year ago should stop showing as broken" --
-- is answered by READING `last_seen` (that is what game_failures_recent_idx is
-- for), not by deleting history. An earlier draft shipped a SECURITY DEFINER
-- prune_game_failures() with no caller; `npm run audit:ci` correctly flagged it,
-- because elevated-privilege code nobody calls can only ever be invoked by
-- accident or by someone who should not be invoking it. If a retention sweep is
-- ever genuinely wanted, add it together with the job that calls it.

-- =====================================================================
-- Verify:
--   select count(*) from public.game_failures;   -- 0 on a fresh install
--   select count(*) from public.web_vitals;      -- 0, and <= 180 forever
--
-- The server degrades gracefully if you never run this file: telemetry stays
-- in memory, is visible in the admin console, and is lost on restart. Nothing
-- breaks and no request fails -- the same posture as game_stats.
-- =====================================================================


-- ============================================================================
-- >>> schema-hardening.sql
-- ============================================================================
-- db/schema-hardening.sql — corrections found by a full audit of the SQL layer.
--
-- Runs LAST, after db/feedback.sql. Like that file, it exists as a NEW migration
-- rather than an edit to the ones before it: those have already been applied to
-- production, and the Supabase integration will not re-run a file it has already
-- recorded. Editing an applied migration changes only the repository's account of
-- the database, never the database — which is the worst of both, because the two
-- then disagree while appearing to agree.
--
-- Four independent corrections. Each is idempotent and each is a no-op on a
-- database that never had the defect.


-- ── 1. The leaderboard teardown missed the function it was aiming at ────────
--
-- db/feedback.sql retires the leaderboard and says, in its own header, that it
-- "removes two SECURITY DEFINER functions — code that runs with elevated rights
-- and should not exist without a caller." It drops:
--
--     submit_score(text, text, integer, text)
--     submit_score(text, text, integer)
--     prune_scores(integer)
--
-- but the function db/community-scores-unique.sql actually created is
--
--     submit_score(text, text, BIGINT)                     -- p_score bigint
--
-- and Postgres identifies a function by name AND argument types. So the two
-- drops named above matched nothing, and the real function survived the
-- teardown: a SECURITY DEFINER routine, still present, whose body inserts into
-- public.scores — a table that no longer exists. Every call raises
-- `relation "public.scores" does not exist`.
--
-- It is revoked from anon and authenticated, so this was never reachable from a
-- browser. It is dead elevated-privilege code that the repository believed was
-- already gone, which is its own problem: the next person to audit the database
-- finds a SECURITY DEFINER function that no file admits to keeping.
--
-- Only the bigint spelling is dropped here. Repeating the other two would be
-- theatre: db/feedback.sql already issues them, it always runs first, and a
-- `drop … if exists` for a signature that was never created is a no-op whose
-- only effect is to make the next reader wonder what it was for.
drop function if exists public.submit_score(text, text, bigint);


-- ── 2. Two prune functions where one is called ──────────────────────────────
--
-- db/admin.sql created prune_admin_state(integer, integer, integer). db/feedback.sql
-- later created prune_admin_logs(integer, integer, integer), which does the same
-- work plus the expired-session sweep, and that is the one lib/cron-jobs.mjs
-- calls. Nothing anywhere calls prune_admin_state — not the server, not a tool,
-- not a runbook.
--
-- It is not merely unused. prune_admin_logs deliberately floors its arguments
-- (`greatest(attempts_days, 7)`, and a hard one-year floor on the audit trail)
-- so that a caller passing 0 cannot erase the record. prune_admin_state has no
-- floors at all: prune_admin_state(0, 0, 0) deletes every login attempt and every
-- security event on the spot. Keeping the unfloored predecessor next to the
-- floored replacement means the safety is one argument away from being bypassed.
drop function if exists public.prune_admin_state(integer, integer, integer);


-- ── 3. Two functions do not pin search_path ─────────────────────────────────
--
-- db/schema.sql sets the house standard and explains it: `security invoker` plus
-- `set search_path = ''` clears Supabase's "Function Search Path Mutable"
-- advisor, and now() still resolves because pg_catalog is implicitly present
-- even with an empty search_path. games_set_updated_at() follows it.
--
-- These two were written later and did not. They are re-declared here with the
-- same bodies and the hardening added, so the whole schema passes the advisor
-- rather than most of it. CREATE OR REPLACE keeps the existing triggers bound —
-- replacing a function does not detach the triggers that use it, so nothing has
-- to be recreated and there is no window where the audit table is writable.
create or replace function public.admin_audit_is_append_only()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  raise exception 'admin_audit_logs is append-only (attempted %)', tg_op;
end $$;

create or replace function public.touch_game_fingerprints()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end $$;


-- ── 4. The orphan-counter sweep deletes counters for games that ARE served ──
--
-- prune_orphan_game_stats() deletes every game_stats row whose slug is not in
-- public.games. That rests on an assumption which is false in this application:
-- that public.games is the whole catalog.
--
-- It is not. server.js builds the served catalog in setCatalog(), which starts
-- from the Supabase rows and then calls mergeFinalGames() — appending every
-- entry of finalgames.json whose slug is NOT already present — and then
-- applyCatalogOverrides(), whose `add` rules inject four more. Those games are
-- appended precisely BECAUSE they are absent from public.games. Roughly 76 of
-- the ~12,300 served games therefore exist only in the repository's JSON.
--
-- Play them and POST /api/play increments the counter; flushPlayStats() upserts
-- it into game_stats a minute later; the weekly sweep sees a slug that is not in
-- public.games and deletes it. Those games are pinned at zero plays forever, so
-- popularity ranking can never learn anything about them no matter how much they
-- are played — the one signal the ranking blend weights most heavily.
--
-- The intent of the sweep is right; its evidence was wrong. "Absent from
-- public.games" does not mean delisted. What does mean delisted is that nobody
-- has played it since: flushPlayStats() writes updated_at on every flush, so a
-- counter that is still moving is proof the game is still reachable, whatever
-- public.games says. A genuinely delisted game stops being played, its
-- updated_at freezes, and it ages out on the next sweep after the grace period.
--
-- The signature stays zero-argument on purpose. Adding `stale_days integer
-- default 90` would create a SECOND function of this name, and PostgREST would
-- then refuse rpc('prune_orphan_game_stats', {}) as ambiguous — the same
-- overload trap that let submit_score survive in section 1 above.
create or replace function public.prune_orphan_game_stats()
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  n bigint;
  -- Long enough that a real player's counter is never collected, short enough
  -- that a delisted game's row does not outlive its usefulness by much.
  grace interval := interval '90 days';
begin
  delete from public.game_stats gs
   where not exists (select 1 from public.games g where g.slug = gs.slug)
     and gs.updated_at < now() - grace;
  get diagnostics n = row_count;
  return n;
end;
$$;

revoke all on function public.prune_orphan_game_stats() from public, anon, authenticated;

comment on function public.prune_orphan_game_stats is
  'Deletes game_stats rows whose slug is neither in games NOR touched in 90 days. The staleness clause is load-bearing: ~76 served games live only in finalgames.json / catalog-overrides and are absent from games by design.';


-- ============================================================================
-- >>> grants.sql
-- ============================================================================
-- =====================================================================
-- ZoFHub · role grants   (MUST RUN LAST — after every table exists)
-- =====================================================================
-- WHY THIS FILE EXISTS
--
-- Creating a table grants nobody anything. Postgres gives a new table's
-- privileges to its owner and to nobody else; every other role needs an
-- explicit GRANT. Supabase normally papers over this with ALTER DEFAULT
-- PRIVILEGES set up at project creation, so tables made in the SQL editor
-- silently arrive with anon / authenticated / service_role grants already
-- attached — and this schema was written against a project where that was
-- true, so it never issued a single GRANT for service_role.
--
-- That assumption did not survive moving to a new project. Every table came
-- up unreadable:
--
--     GET /rest/v1/games  ->  403
--     {"code":"42501","message":"permission denied for table games",
--      "hint":"Grant the required privileges to the current role with:
--              GRANT SELECT ON public.games TO service_role;"}
--
-- Note the hint names service_role. The key was correct and the role was
-- correct; the grant was simply never made. `npm run restore-games` failed
-- all 34 batches with 0 rows written, and the schema audit still reported
-- clean, because the tables genuinely did exist — nothing could read them.
--
-- Depending on inherited default privileges is depending on how a project
-- happened to be provisioned. This file states the privileges outright, so
-- the schema is complete on any project, old or new.
--
-- PRIVILEGE MODEL
--
--   service_role  The Node server's identity (SUPABASE_SECRET_KEY). Full DML
--                 on everything; bypasses RLS. This is the only role the
--                 application actually uses — public/ contains no Supabase
--                 client, so the browser never talks to PostgREST directly.
--
--   anon /        Granted SELECT on exactly the five relations that already
--   authenticated carry a permissive read policy, and INSERT on feedback.
--                 The GRANT is the outer gate and RLS is the inner one; both
--                 must pass. Granting no more than the policies already allow
--                 keeps the two consistent, so neither is load-bearing alone.
--                 Explicitly revoked on everything else — admin tables, the
--                 discovery tables, and feedback reads.
--
-- Idempotent: GRANT/REVOKE are declarative, so re-running changes nothing.
-- Every role is probed before use, so this also runs on a plain Postgres that
-- has no Supabase roles at all.
-- =====================================================================

do $$
declare
  -- Relations a permissive SELECT policy already exposes:
  --   games            RLS: is_working = true
  --   games_public     SECURITY INVOKER view over games (needs both grants)
  --   recommendations  RLS: is_visible = true
  --   keepalive        RLS: true
  --   game_stats       RLS: true
  public_read constant text[] := array[
    'games', 'games_public', 'recommendations', 'keepalive', 'game_stats'
  ];

  -- Server-only. No public policy exists for these, and none should: the
  -- admin tables are the audit trail and session store, the discovery tables
  -- hold provider fingerprints, and feedback is private correspondence.
  -- feedback keeps its INSERT grant (that is how the contact form works) but
  -- must never become readable.
  private_read constant text[] := array[
    'feedback', 'admin_sessions', 'admin_audit_logs', 'admin_login_attempts',
    'admin_security_events', 'game_fingerprints', 'game_duplicates',
    'rejected_submissions'
  ];

  rel          text;
  -- Not named `role`: that is a Postgres keyword, and a variable sharing a
  -- name with SQL syntax is how a working DO block turns into a parse error
  -- the next time someone edits a statement inside it.
  grantee_role text;
begin
  -- ── The server ────────────────────────────────────────────────────────
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant usage on schema public to service_role';
    execute 'grant all privileges on all tables    in schema public to service_role';
    execute 'grant all privileges on all sequences in schema public to service_role';
    execute 'grant all privileges on all functions in schema public to service_role';

    -- ...and for tables added by future migrations, so the next person to add
    -- one does not rediscover this bug. Default privileges are recorded per
    -- granting role; the SQL editor and the Supabase GitHub integration both
    -- run as the owner, which is the role that matters here.
    execute 'alter default privileges in schema public grant all privileges on tables    to service_role';
    execute 'alter default privileges in schema public grant all privileges on sequences to service_role';
    execute 'alter default privileges in schema public grant all privileges on functions to service_role';

    raise notice 'granted public schema to service_role';
  else
    raise notice 'no service_role on this database — skipped (not a Supabase project?)';
  end if;

  -- ── The public keys ───────────────────────────────────────────────────
  foreach grantee_role in array array['anon', 'authenticated'] loop
    continue when not exists (select 1 from pg_roles where rolname = grantee_role);

    execute format('grant usage on schema public to %I', grantee_role);

    foreach rel in array public_read loop
      -- to_regclass returns NULL rather than raising, so a relation an
      -- earlier migration dropped (scores, retired with the leaderboard)
      -- or has not created yet is skipped instead of failing the deploy.
      continue when to_regclass('public.' || rel) is null;
      execute format('grant select on public.%I to %I', rel, grantee_role);
    end loop;

    foreach rel in array private_read loop
      continue when to_regclass('public.' || rel) is null;
      execute format('revoke all on public.%I from %I', rel, grantee_role);
    end loop;

    -- Restored after the blanket revoke above: anonymous visitors must be
    -- able to send feedback, they just must not be able to read it back.
    -- RLS ("Anyone may send feedback") still applies on top.
    if to_regclass('public.feedback') is not null then
      execute format('grant insert on public.feedback to %I', grantee_role);
    end if;
  end loop;
end $$;


-- ---------------------------------------------------------------------
-- Sanity check — what each role can actually reach now.
-- ---------------------------------------------------------------------
-- Expect: service_role on every table; anon/authenticated only on the five
-- policy-backed relations plus INSERT on feedback.
select
  grantee,
  table_name,
  string_agg(privilege_type, ', ' order by privilege_type) as privileges
from information_schema.role_table_grants
where table_schema = 'public'
  and grantee in ('anon', 'authenticated', 'service_role')
group by grantee, table_name
order by grantee, table_name;
